TOOL_DEFINITIONS = {item["function"]["name"]: item["function"] for item in TOOLS}


def safe_path(path_str):
    try:
        candidate = Path(path_str)
        if not candidate.is_absolute():
            candidate = WORKSPACE / candidate
        resolved = candidate.resolve()
        return resolved if resolved.is_relative_to(WORKSPACE) else None
    except Exception:
        return None


def tool_argument_error(name, args):
    definition = TOOL_DEFINITIONS.get(name)
    if definition is None:
        return None
    if not isinstance(args, dict):
        return f"error: {name} arguments must be one JSON object"
    required = definition.get("parameters", {}).get("required", [])
    missing = [key for key in required if key not in args or args.get(key) is None]
    if not missing:
        return None
    return (
        f"error: incomplete or truncated {name} tool call; missing: {', '.join(missing)}. "
        "Retry with every required field and smaller content/edit fragments. No file was changed."
    )


def begin_transaction(task_id):
    global ACTIVE_TRANSACTION, LAST_COMMITTED_TRANSACTION
    if ACTIVE_TRANSACTION is not None:
        raise RuntimeError(f"transaction already active for {ACTIVE_TRANSACTION['task_id']}")
    LAST_COMMITTED_TRANSACTION = None
    ACTIVE_TRANSACTION = {"task_id": task_id, "files": {}}


def _transaction_capture(target):
    if ACTIVE_TRANSACTION is None:
        return
    key = str(target)
    if key in ACTIVE_TRANSACTION["files"]:
        return
    ACTIVE_TRANSACTION["files"][key] = {
        "existed": target.exists(),
        "content": target.read_bytes() if target.exists() and target.is_file() else None,
    }


def commit_transaction():
    global ACTIVE_TRANSACTION, LAST_COMMITTED_TRANSACTION
    transaction = ACTIVE_TRANSACTION or {"task_id": None, "files": {}}
    ACTIVE_TRANSACTION = None
    LAST_COMMITTED_TRANSACTION = transaction
    changed = sorted(transaction["files"])
    _world_model_revalidate_after_files(changed, phase="commit")
    record_run_event("transaction_commit", task_id=transaction.get("task_id"), changed=changed)
    return changed


def rollback_transaction():
    global ACTIVE_TRANSACTION
    transaction = ACTIVE_TRANSACTION
    ACTIVE_TRANSACTION = None
    if not transaction:
        return []
    restored = []
    for raw_path, snapshot in transaction["files"].items():
        target = Path(raw_path)
        try:
            if snapshot["existed"]:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(snapshot["content"])
            elif target.exists() and target.is_file():
                target.unlink()
            restored.append(raw_path)
            store = get_memory_store()
            if store:
                store.reconcile_rolled_back_artifact(raw_path, existed=bool(snapshot["existed"]))
        except OSError as exc:
            print(f"[ROLLBACK_ERROR] {target}: {exc}")
    _world_model_revalidate_after_files(restored, phase="rollback")
    record_run_event("transaction_rollback", task_id=transaction.get("task_id"), restored=restored)
    return restored


def backup(target):
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    relative = target.relative_to(WORKSPACE)
    path = WORKSPACE / ".agent_backups" / (RUN_ID or stamp) / relative
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            path = path.with_name(path.name + f".{stamp}")
        shutil.copy2(target, path)
        return f" (managed backup: {path.relative_to(WORKSPACE)})"
    except OSError as exc:
        return f"error: backup failed, file NOT changed: {exc}"


def source_validation_error(target, content):
    suffix = target.suffix.casefold()
    text = str(content)
    if suffix == ".py":
        try:
            compile(text, str(target), "exec")
        except SyntaxError as exc:
            return f"Python syntax validation failed at line {exc.lineno}: {exc.msg}"
        return None
    if suffix == ".json":
        try:
            json.loads(text)
        except (ValueError, TypeError) as exc:
            return f"JSON syntax validation failed: {exc}"
        return None
    javascript = text if suffix in {".js", ".mjs", ".cjs"} else ""
    if suffix in {".html", ".htm"}:
        javascript = "\n;\n".join(re.findall(
            r"<script(?![^>]*\bsrc=)(?![^>]*type=[\"'](?:application|application/ld)\/json[\"'])[^>]*>([\s\S]*?)</script>",
            text, flags=re.IGNORECASE,
        ))
    if not javascript.strip():
        return None
    try:
        checked = subprocess.run(
            ["node", "--check", "-"], input=javascript, text=True,
            encoding="utf-8", errors="replace", capture_output=True, timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if checked.returncode != 0:
        return f"JavaScript syntax validation failed: {compact_text(checked.stderr or checked.stdout, 500)}"
    return None


def _precommit_invariant_feedback(target, candidate, *, tool_name, original=None,
                                  pre_state_bytes=None):
    """Run the bound semantic gate at the last pre-write mutation boundary."""
    if not RUN.get("stage6c_enabled"):
        return None
    invariant_set = RUN.get("execution_invariant_set")
    authorization = RUN.get("execution_authorization")
    # V25.1/V25.3 compatibility executions may predate the optional V25.2
    # invariant binding.  They have no semantic authority to enforce here;
    # importantly, this path never derives a replacement set at mutation time.
    if (
        not isinstance(invariant_set, dict)
        or not invariant_set.get("invariant_set_hash")
    ):
        return None
    active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
    effective = active.get("execution_contract") if isinstance(active.get("execution_contract"), dict) else None
    if not isinstance(effective, dict):
        effective = _current_execution_contract(active) if active else None
    try:
        relative = target.relative_to(Path(WORKSPACE).resolve()).as_posix()
    except (AttributeError, OSError, RuntimeError, TypeError, ValueError):
        relative = str(target)
    mutation_id = "{}-{}".format(
        str(tool_name).upper(),
        stage6c.canonical_hash({
            "path": relative,
            "pre_state_hash": hashlib.sha256(
                pre_state_bytes if isinstance(pre_state_bytes, bytes)
                else str(original or "").encode("utf-8")
            ).hexdigest(),
            "candidate_hash": hashlib.sha256(str(candidate).encode("utf-8")).hexdigest(),
        })[:24].upper(),
    )
    gate = stage6c_precommit.PreCommitExecutionInvariantGate(
        invariant_set,
        contract=effective,
        # A supplied set without a current binding is a fail-closed gate
        # input.  Legacy executions skip only when no set is present at all.
        authorization=authorization if isinstance(authorization, dict) else {},
        workspace=WORKSPACE,
    )
    audit = gate.evaluate(
        relative,
        candidate,
        original_content=original,
        pre_state_bytes=pre_state_bytes,
        mutation_id=mutation_id,
    )
    audit_value = copy.deepcopy(audit)
    RUN["precommit_invariant_gate_calls"] = RUN.get("precommit_invariant_gate_calls", 0) + 1
    RUN.setdefault("precommit_invariant_audits", []).append(audit_value)
    RUN["precommit_invariant_audits"] = RUN["precommit_invariant_audits"][-32:]
    if not audit.get("allowed"):
        RUN["precommit_invariant_gate_rejections"] = RUN.get(
            "precommit_invariant_gate_rejections", 0,
        ) + 1
    record_run_event(
        "precommit_invariant_audit",
        tool=tool_name,
        target=relative,
        status=audit.get("status"),
        allowed=audit.get("allowed"),
        audit_hash=audit.get("canonical_hash"),
        invariant_ids=list(audit.get("applicable_invariant_ids", []) or []),
        violations=list(audit.get("violations", []) or []),
        model_calls=0,
        worker_calls=0,
    )
    if audit.get("allowed"):
        return None
    return stage6c_precommit.format_precommit_invariant_feedback(audit)


def write_file(path, content, role="System"):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if role == "Repairer":
        return "error: Repairer cannot replace files with write_file; use focused edits"
    transaction_snapshot = (ACTIVE_TRANSACTION or {}).get("files", {}).get(str(target))
    created_here = bool(transaction_snapshot and not transaction_snapshot.get("existed"))
    resumable = False
    if target.exists() and role == "Builder" and not created_here:
        store = get_memory_store()
        resumable = bool(ACTIVE_TRANSACTION is not None and store and store.is_unverified_model_artifact(target))
        if not resumable:
            return "error: write_file cannot replace an existing user-owned or verified file; use focused edit_file"
    validation = source_validation_error(target, content)
    if validation:
        return f"error: {validation}; file was not changed"
    pre_state_bytes = None
    if target.exists() and target.is_file():
        try:
            pre_state_bytes = target.read_bytes()
        except OSError:
            pre_state_bytes = None
    gate_issue = _precommit_invariant_feedback(
        target, content, tool_name="write_file", pre_state_bytes=pre_state_bytes,
    )
    if gate_issue:
        return gate_issue
    note = backup(target) if target.exists() and not created_here else ""
    if note.startswith("error"):
        return note
    try:
        _transaction_capture(target)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        # The source changed before verification can run.  Any semantic fact
        # sourced from it is immediately stale and cannot serve a later
        # resolver/gate request during this transaction.
        _world_model_invalidate_paths([target], phase="mutation")
        if target.exists() and created_here:
            return f"wrote file: {target}{note}"
        if resumable:
            return f"wrote file: {target} (resumed unverified model artifact){note}"
        return f"wrote file: {target}{note}"
    except OSError as exc:
        return f"error writing file: {exc}"


def edit_file(path, old, new, expected_replacements=1):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if not target.exists() or not target.is_file():
        return f"error: file does not exist: {target}"
    try:
        original = target.read_text(encoding="utf-8")
    except OSError as exc:
        return f"error reading file: {exc}"
    expected = expected_replacements or 1
    actual = original.count(old)
    if actual != expected:
        return f"error: expected {expected} exact replacement(s), found {actual}; file was not changed"
    candidate = original.replace(old, new, expected)
    validation = source_validation_error(target, candidate)
    if validation:
        return f"error: {validation}; edit rejected and file was not changed"
    try:
        pre_state_bytes = target.read_bytes()
    except OSError:
        pre_state_bytes = None
    gate_issue = _precommit_invariant_feedback(
        target, candidate, tool_name="edit_file", original=original,
        pre_state_bytes=pre_state_bytes,
    )
    if gate_issue:
        return gate_issue
    snapshot = (ACTIVE_TRANSACTION or {}).get("files", {}).get(str(target))
    transaction_owned = bool(snapshot and not snapshot.get("existed"))
    note = "" if transaction_owned else backup(target)
    if note.startswith("error"):
        return note
    try:
        _transaction_capture(target)
        target.write_text(candidate, encoding="utf-8")
        _world_model_invalidate_paths([target], phase="mutation")
        return f"edited file: {target} ({expected} replacement(s)){note}"
    except OSError as exc:
        return f"error writing file: {exc}"


def read_file_range(path, start_line=1, end_line=None):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if not target.exists() or not target.is_file():
        return f"error: file does not exist: {target}"
    try:
        lines = target.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        return f"error reading file: {exc}"
    start = max(1, int(start_line or 1))
    end = min(len(lines), int(end_line or min(len(lines), start + 199)))
    if start > len(lines) or end < start:
        return f"error: invalid line range {start}-{end}; file has {len(lines)} lines"
    return f"[lines {start}-{end} of {len(lines)}]\n" + "\n".join(
        f"{number}: {line}" for number, line in enumerate(lines[start - 1:end], start=start)
    )


def edit_file_range(path, start_line, end_line, new, role="System"):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if not target.exists() or not target.is_file():
        return f"error: file does not exist: {target}"
    try:
        original = target.read_text(encoding="utf-8")
    except OSError as exc:
        return f"error reading file: {exc}"
    lines = original.splitlines(keepends=True)
    start, end = int(start_line), int(end_line)
    if start < 1 or end < start or end > len(lines):
        return f"error: invalid line range {start}-{end}; file has {len(lines)} lines"
    snapshot = (ACTIVE_TRANSACTION or {}).get("files", {}).get(str(target))
    transaction_owned = bool(snapshot and not snapshot.get("existed"))
    span = end - start + 1
    if not transaction_owned and role in {"Builder", "Repairer"} and span > max(120, int(len(lines) * 0.6)):
        return "error: requested range is too broad for a pre-existing file; use smaller verified edits"
    replacement = str(new)
    if end < len(lines) and replacement and not replacement.endswith(("\n", "\r")):
        replacement += "\n"
    candidate = "".join(lines[:start - 1]) + replacement + "".join(lines[end:])
    validation = source_validation_error(target, candidate)
    if validation:
        return f"error: {validation}; edit rejected and file was not changed"
    try:
        pre_state_bytes = target.read_bytes()
    except OSError:
        pre_state_bytes = None
    gate_issue = _precommit_invariant_feedback(
        target, candidate, tool_name="edit_file_range", original=original,
        pre_state_bytes=pre_state_bytes,
    )
    if gate_issue:
        return gate_issue
    note = "" if transaction_owned else backup(target)
    if note.startswith("error"):
        return note
    try:
        _transaction_capture(target)
        target.write_text(candidate, encoding="utf-8")
        _world_model_invalidate_paths([target], phase="mutation")
        return f"edited lines {start}-{end} in file: {target}{note}"
    except OSError as exc:
        return f"error writing file: {exc}"


def read_file(path):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if not target.exists():
        return f"error: file does not exist: {target}"
    try:
        return target.read_text(encoding="utf-8")
    except OSError as exc:
        return f"error reading file: {exc}"


def backup_file(path):
    target = safe_path(path)
    if target is None or not target.exists():
        return "error: file does not exist or escapes workspace"
    return f"backup created for {target}{backup(target)}"


def coherent_rewrite_preflight(args):
    """Reject an obvious fragment before an optional full-draft rewrite.

    The adaptive path does not use a separate rewrite scheduler, but keeping
    this narrow guard protects callers that explicitly request a whole-draft
    recovery from accidentally replacing a large artifact with one function.
    """
    if not isinstance(args, dict):
        return "error: rewrite arguments must be an object; No file was changed"
    target = safe_path(args.get("path", ""))
    content = args.get("content")
    if target is None or content is None:
        return "error: rewrite path and content are required; No file was changed"
    if target.exists() and target.is_file():
        try:
            existing_lines = target.read_text(encoding="utf-8").splitlines()
        except OSError as exc:
            return f"error: could not inspect rewrite target: {exc}; No file was changed"
        new_lines = str(content).splitlines()
        if len(existing_lines) >= 20 and len(new_lines) < max(3, int(len(existing_lines) * 0.4)):
            return "error: proposed rewrite appears to be a fragment of the existing artifact; No file was changed"
    return None


def list_files():
    try:
        hidden = {
            MEMORY_FILE, EXPERIMENT_FILE, EVIDENCE_DIR, RUNS_DIR, ".hivo", ".agent_backups",
            ".git", ".venv", "__pycache__", "node_modules",
        }
        names = [p.name for p in sorted(WORKSPACE.iterdir()) if p.name not in hidden and ".backup_" not in p.name]
        return "\n".join(names) if names else "(workspace is empty)"
    except OSError as exc:
        return f"error listing files: {exc}"


def run_file(path):
    target = safe_path(path)
    if target is None:
        return f"error: '{path}' is outside the workspace."
    if not target.exists():
        return f"error: file does not exist: {target}"
    ext = target.suffix.lower()
    try:
        if ext == ".py":
            cmd = [sys.executable, str(target)]
        elif ext == ".js":
            source = target.read_text(encoding="utf-8", errors="replace")
            if re.search(r"\b(?:document|localStorage|sessionStorage|navigator|requestAnimationFrame)\b|\bwindow\s*[.[]", source):
                return "[not_applicable] browser-target JavaScript must be verified in a browser with verify_web_app"
            cmd = ["node", str(target)]
        elif ext in (".cpp", ".cc"):
            exe = target.with_suffix(".out")
            build = subprocess.run(["g++", str(target), "-o", str(exe)], cwd=WORKSPACE,
                                   capture_output=True, text=True, timeout=30)
            if build.returncode != 0:
                return f"compile error:\n{build.stderr}"
            cmd = [str(exe)]
        elif ext in (".html", ".htm"):
            return json.dumps(
                verify_browser_application(
                    path, "run_file", evidence={"requested_from_node": path},
                ),
                ensure_ascii=False,
            )
        else:
            return f"error: unsupported file type for running: {ext}"
        result = subprocess.run(cmd, cwd=WORKSPACE, capture_output=True, text=True, timeout=30)
        output = (result.stdout + result.stderr).strip()
        return f"[exit_code={result.returncode}]\n{output or '(no output)'}"
    except subprocess.TimeoutExpired:
        return "error: execution timed out (30s limit)"
    except FileNotFoundError as exc:
        return f"error: required interpreter/compiler not found: {exc}"
    except Exception as exc:
        return f"error running file: {exc}"


def _validated_command_parts(command):
    lower = command.lower()
    if any(bad in lower for bad in DANGEROUS) or any(token in command for token in ("\n", "\r", "&&", "||", ";", "|", ">", "<")):
        return None, "dangerous commands and shell composition are not allowed"
    try:
        parts = shlex.split(command, posix=(os.name != "nt"))
        parts = [part.strip('"') for part in parts]
    except ValueError as exc:
        return None, f"could not parse command: {exc}"
    if not parts:
        return None, "empty command"
    executable = Path(parts[0]).stem.lower()
    allowed = {"python", "python3", "py", "node", "npm", "npx", "pytest", "git", "g++", "clang++", "tsc"}
    if executable not in allowed:
        return None, f"executable '{executable}' is not in the verification allowlist"
    if executable in {"python", "python3", "py"} and "-c" in parts:
        return None, "inline Python is not allowed"
    if executable == "node" and any(flag in parts for flag in ("-e", "--eval")):
        return None, "inline Node.js is not allowed"
    if executable == "git":
        subcommand = next((part for part in parts[1:] if not part.startswith("-")), "")
        if subcommand not in {"status", "diff", "log", "show", "ls-files", "rev-parse"}:
            return None, f"git subcommand '{subcommand}' is not read-only"
    if executable == "npm" and any(word in parts[1:] for word in ("install", "uninstall", "publish", "link")):
        return None, "package mutation is not allowed from run_command"
    if executable == "npx":
        requested = next((Path(part).stem.lower() for part in parts[1:] if not part.startswith("-")), "")
        if requested not in {"eslint", "tsc", "vitest", "jest", "playwright", "vite"}:
            return None, f"npx tool '{requested}' is not in the verification allowlist"
    for part in parts[1:]:
        if part.startswith("-") or "://" in part:
            continue
        candidate = Path(part)
        looks_like_path = candidate.is_absolute() or ".." in candidate.parts or "/" in part or "\\" in part
        if looks_like_path:
            resolved = candidate.resolve() if candidate.is_absolute() else (WORKSPACE / candidate).resolve()
            if not resolved.is_relative_to(WORKSPACE):
                return None, f"path argument escapes the workspace: {part}"
    return parts, None


def run_command(command):
    parts, error = _validated_command_parts(command)
    if error:
        return f"error: command refused: {error}"
    try:
        result = subprocess.run(parts, shell=False, cwd=WORKSPACE, capture_output=True, text=True, timeout=60)
        output = (result.stdout + result.stderr).strip()
        return f"[exit_code={result.returncode}]\n{output or '(no output)'}"
    except subprocess.TimeoutExpired:
        return "error: command timed out (60s limit)"
    except Exception as exc:
        return f"tool error: {exc}"


def tools_for_role(role, tool_policy=None, recovery_strategy=None):
    """Return the role tools, optionally projected for one recovery epoch.

    The default path is byte-for-byte equivalent to the existing role
    projection.  Recovery suppression is opt-in and is applied only to the
    supplied local recovery strategy state, never to the global registry.
    """
    if role == "Falsifier":
        allowed = {"read_file", "read_file_range", "list_files", "run_file", "run_command", "verify_web_app"}
        base = [tool for tool in TOOLS if tool["function"]["name"] in allowed]
    elif role == "Repairer":
        allowed = {"edit_file", "edit_file_range", "read_file", "read_file_range", "list_files", "run_file", "run_command", "verify_web_app"}
        base = [tool for tool in TOOLS if tool["function"]["name"] in allowed]
    elif tool_policy == "coherent_rewrite":
        allowed = {"write_file", "read_file", "read_file_range", "list_files", "run_file", "run_command", "verify_web_app"}
        base = [tool for tool in TOOLS if tool["function"]["name"] in allowed]
    else:
        base = [tool for tool in TOOLS if tool["function"]["name"] != _CONTEXT_COMPLETION_TOOL]
    if isinstance(recovery_strategy, dict):
        strategy = recovery_strategy.get("current_strategy")
        if not isinstance(strategy, dict) and recovery_strategy.get("artifact_type") == RECOVERY_MUTATION_STRATEGY:
            strategy = recovery_strategy
        if isinstance(strategy, dict):
            return stage6d.project_recovery_tool_schemas(base, strategy)
    return base


def recovery_tools_for_epoch(role="Builder", recovery_strategy=None, tool_policy=None):
    """Explicit public spelling for the local recovery tool projection."""
    return tools_for_role(role, tool_policy=tool_policy, recovery_strategy=recovery_strategy)


_CONTEXT_MUTATION_TOOLS = MUTATION_TOOLS
_CONTEXT_COMPLETION_TOOL = "context_sufficiency_check"
_CONTEXT_PROVIDER_MAX_FILES = 8
_CONTEXT_PROVIDER_MAX_EXCERPTS_PER_REQUEST = 2
_CONTEXT_PROVIDER_EXCERPT_CHARS = 650
_CONTEXT_PROVIDER_FILE_CHARS = 120000
_CONTEXT_SOURCE_EXTENSIONS = frozenset({
    ".py", ".pyi", ".js", ".mjs", ".cjs", ".jsx", ".ts", ".tsx", ".html", ".htm",
    ".css", ".scss", ".json", ".toml", ".yaml", ".yml", ".go", ".rs", ".java", ".c",
    ".cpp", ".h", ".md", ".txt",
})


def _active_context_gate(role=None):
    gate = ACTIVE_CONTEXT_SUFFICIENCY_GATE
    if role is not None and role not in {"Builder", "Repairer"}:
        return None
    return gate if isinstance(gate, stage7_context.ContextSufficiencyGate) else None


def _context_gate_mutation_guard(name, role="System", target=None):
    """Fail closed at the runtime mutation seam while context is incomplete."""
    if name not in _CONTEXT_MUTATION_TOOLS or role not in {"Builder", "Repairer"}:
        return None
    issue = stage7_context.mutation_block_reason(_active_context_gate(role))
    if issue:
        RUN["context_sufficiency_blocks"] = RUN.get("context_sufficiency_blocks", 0) + 1
        record_run_event(
            "context_sufficiency_mutation_blocked",
            role=role,
            task_id=(ACTIVE_TOOL_CONTRACT or {}).get("task_id") if isinstance(ACTIVE_TOOL_CONTRACT, dict) else None,
            tool=name,
            target=compact_text(target if target is not None else "-", 180),
            reason=compact_text(issue, 420),
        )
    return issue


def _context_tool_projection(tools, gate):
    """Project tools without weakening the existing role/recovery policy."""
    if gate is None:
        return tools
    projected = list(tools or [])
    if not gate.mutation_allowed:
        projected = [
            item for item in projected
            if item.get("function", {}).get("name") not in _CONTEXT_MUTATION_TOOLS
        ]
    if not any(item.get("function", {}).get("name") == _CONTEXT_COMPLETION_TOOL for item in projected):
        completion_tool = next(
            (item for item in TOOLS if item.get("function", {}).get("name") == _CONTEXT_COMPLETION_TOOL),
            None,
        )
        if completion_tool is not None:
            projected.insert(0, completion_tool)
    # The impact contract is a second controller gate.  Apply it after the
    # existing context projection so context completion can restore only the
    # tools that both gates currently authorize.
    if ACTIVE_IMPACT_REQUIRED or RUN.get("impact_contract_required"):
        projected = _impact_tool_projection(projected, required=True)
    return projected


# ---------------------------------------------------------------------------
# V30 bounded pre-mutation impact contract
# ---------------------------------------------------------------------------

def _impact_required_for_worker(role, *, context_gate=None, explicit=None,
                                execution_contract=None):
    """Decide whether this synchronous Worker attempt needs the second gate.

    Legacy direct tool callers do not enter this path.  Production Builder /
    Repairer attempts, and explicit tests/approval paths, do.
    """
    if role not in {"Builder", "Repairer"}:
        return False
    if explicit is True:
        return True
    if ACTIVE_IMPACT_REQUIRED or RUN.get("impact_contract_required"):
        return True
    if context_gate is not None:
        return True
    if explicit is False:
        return False
    return bool(isinstance(execution_contract, dict) and execution_contract.get("worker_required"))


def _impact_effective_contract(value):
    if not isinstance(value, dict):
        return {}
    nested = value.get("execution_contract")
    return nested if isinstance(nested, dict) else value


def _impact_candidate_for_worker(task_text, task_id, *, candidate=None,
                                 context_anchor=None, execution_contract=None,
                                 mutation_required=True):
    if isinstance(candidate, dict):
        return copy.deepcopy(candidate)
    active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
    effective = _impact_effective_contract(execution_contract)
    anchor = context_anchor if isinstance(context_anchor, dict) else {}
    task = {
        "id": task_id,
        "goal": str(task_text or ""),
        "parent_goal": anchor.get("parent_goal"),
        "root_goal": anchor.get("root_goal"),
        "semantic_group_goal": anchor.get("group_goal"),
        "semantic_group_invariant": anchor.get("group_invariant"),
        "done_when": anchor.get("requirements") or active.get("requirements") or effective.get("requirements", []),
        "scope_hint": effective.get("allowed_mutation_paths", []),
        "allowed_mutation_paths": effective.get("allowed_mutation_paths", []),
        "local_preservation_constraints": anchor.get("constraints") or effective.get("local_preservation_constraints", []),
        "execution_contract": effective,
        "verification_obligations": effective.get("verification_obligations"),
        "test_contract": effective.get("test_contract"),
        "global_do_not_touch": effective.get("global_do_not_touch", []),
    }
    return stage10_impact.build_pre_mutation_impact_contract(
        task,
        task_id=task_id,
        root_goal=anchor.get("root_goal"),
        parent_goal=anchor.get("parent_goal"),
        local_task=anchor.get("local_task") or task_text,
        group_goal=anchor.get("group_goal"),
        group_invariant=anchor.get("group_invariant"),
        execution_contract=effective,
        world_model=_world_model_for_workspace(),
        mutation_required=mutation_required,
        strict=True,
    )


def _impact_validation_context(context_anchor=None, execution_contract=None):
    anchor = context_anchor if isinstance(context_anchor, dict) else {}
    effective = _impact_effective_contract(execution_contract)
    allowed = effective.get("allowed_mutation_paths") or (
        (ACTIVE_TOOL_CONTRACT or {}).get("allowed_mutation_paths", [])
        if isinstance(ACTIVE_TOOL_CONTRACT, dict) else []
    )
    return {
        "world_model": _world_model_for_workspace(),
        "root_goal": anchor.get("root_goal"),
        "parent_goal": anchor.get("parent_goal"),
        "local_task": anchor.get("local_task"),
        "group_goal": anchor.get("group_goal"),
        "allowed_mutation_paths": allowed,
        "forbidden_paths": effective.get("global_do_not_touch", []),
    }


def _impact_record_metrics(validation=None, comparison=None, *, created=False,
                           authorized=False, blocked=False, revised=False):
    if not isinstance(RUN, dict):
        return
    validation = validation if isinstance(validation, dict) else {}
    comparison = comparison if isinstance(comparison, dict) else {}
    if created:
        RUN["impact_contracts_created"] = RUN.get("impact_contracts_created", 0) + 1
    if validation:
        if validation.get("valid"):
            RUN["impact_contracts_validated"] = RUN.get("impact_contracts_validated", 0) + 1
        else:
            RUN["impact_contracts_rejected"] = RUN.get("impact_contracts_rejected", 0) + 1
    if authorized:
        RUN["impact_contract_authorizations"] = RUN.get("impact_contract_authorizations", 0) + 1
    if blocked:
        RUN["impact_contract_mutation_blocks"] = RUN.get("impact_contract_mutation_blocks", 0) + 1
    if revised:
        RUN["impact_contract_revisions"] = RUN.get("impact_contract_revisions", 0) + 1
    if comparison:
        RUN["impact_contract_comparisons"] = RUN.get("impact_contract_comparisons", 0) + 1
        RUN["impact_expected_targets"] = RUN.get("impact_expected_targets", 0) + len(
            comparison.get("comparisons", []) or []
        )
        RUN["impact_missing_targets"] = RUN.get("impact_missing_targets", 0) + len(
            comparison.get("missing", []) or []
        )
        RUN["impact_unexpected_related"] = RUN.get("impact_unexpected_related", 0) + len(
            comparison.get("unexpected_related", []) or []
        )
        RUN["impact_out_of_scope_changes"] = RUN.get("impact_out_of_scope_changes", 0) + len(
            comparison.get("out_of_scope", []) or []
        )
        RUN["impact_preservation_violations"] = RUN.get("impact_preservation_violations", 0) + len(
            comparison.get("preservation_violations", []) or []
        )
        RUN["impact_unresolved_obligations"] = RUN.get("impact_unresolved_obligations", 0) + len(
            comparison.get("unresolved_obligations", []) or []
        )
        if comparison.get("status") == stage10_impact.IMPACT_CONFLICT:
            RUN["impact_conflicts"] = RUN.get("impact_conflicts", 0) + 1


def _activate_impact_contract(candidate, *, context_anchor=None,
                              execution_contract=None, task_id="ROOT"):
    """Validate and install the controller-only mutation authorization."""
    global ACTIVE_IMPACT_CONTRACT, ACTIVE_IMPACT_REQUIRED
    if not isinstance(candidate, dict):
        return {"accepted": False, "status": stage10_impact.IMPACT_REQUIRED,
                "errors": [{"reason": "no impact contract candidate"}], "contract": {}}
    validation = stage10_impact.validate_pre_mutation_impact_contract(
        candidate, **_impact_validation_context(context_anchor, execution_contract),
    )
    _impact_record_metrics(validation)
    if not validation.get("valid"):
        record_run_event(
            "impact_contract_rejected",
            task_id=task_id,
            status=validation.get("status"),
            errors=[compact_text(item.get("reason", ""), 260) for item in validation.get("errors", [])[:6]],
        )
        return validation
    validation_context = _impact_validation_context(context_anchor, execution_contract)
    accepted = stage10_impact.accept_pre_mutation_impact_contract(
        candidate, validation=validation,
        **validation_context,
    )
    if not accepted.get("accepted"):
        _impact_record_metrics({"valid": False, "errors": accepted.get("errors", [])})
        return accepted
    ACTIVE_IMPACT_CONTRACT = copy.deepcopy(accepted["contract"])
    ACTIVE_IMPACT_REQUIRED = True
    RUN["impact_contract_required"] = True
    _impact_record_metrics(authorized=True)
    record_run_event(
        "impact_contract_authorized",
        task_id=task_id,
        contract_id=ACTIVE_IMPACT_CONTRACT.get("contract_id"),
        contract_hash=ACTIVE_IMPACT_CONTRACT.get("contract_hash"),
        revision=ACTIVE_IMPACT_CONTRACT.get("revision", 0),
        mutation_authorized=True,
    )
    return {
        "accepted": True,
        "status": stage10_impact.IMPACT_ACCEPTED,
        "contract": copy.deepcopy(ACTIVE_IMPACT_CONTRACT),
        "validation": validation,
    }


def _clear_impact_attempt():
    global ACTIVE_IMPACT_CONTRACT, ACTIVE_IMPACT_REQUIRED
    ACTIVE_IMPACT_CONTRACT = None
    ACTIVE_IMPACT_REQUIRED = False
    if isinstance(RUN, dict):
        RUN.pop("impact_contract_required", None)


def _impact_gate_mutation_guard(name, role="System", target=None):
    """Fail closed unless a validated controller contract is active."""
    if name not in _CONTEXT_MUTATION_TOOLS or role not in {"Builder", "Repairer"}:
        return None
    required = bool(ACTIVE_IMPACT_REQUIRED or RUN.get("impact_contract_required"))
    if not required:
        return None
    # The impact marker never substitutes for the earlier context gate.  This
    # check also covers explicit Worker callers that forgot to install a gate;
    # legacy direct file helpers do not pass through this Worker seam.
    active_context_gate = _active_context_gate(role)
    # ``context_sufficiency.mutation_block_reason(None)`` is intentionally
    # permissive for legacy non-Worker callers.  Once the Impact Contract
    # policy is active, however, this seam is a Worker mutation boundary and
    # must fail closed when the earlier context gate was never installed.
    context_issue = (
        "error: CONTEXT_SUFFICIENCY_REQUIRED; Worker mutation is blocked because "
        "the Context Sufficiency Gate is not active"
        if active_context_gate is None
        else stage7_context.mutation_block_reason(active_context_gate)
    )
    if context_issue:
        RUN["context_sufficiency_blocks"] = RUN.get("context_sufficiency_blocks", 0) + 1
        return context_issue
    issue = stage10_impact.impact_mutation_block_reason(
        ACTIVE_IMPACT_CONTRACT, required=True,
        world_model=_world_model_for_workspace(),
    )
    if issue:
        _impact_record_metrics(blocked=True)
        record_run_event(
            "impact_contract_mutation_blocked",
            role=role,
            task_id=(ACTIVE_TOOL_CONTRACT or {}).get("task_id") if isinstance(ACTIVE_TOOL_CONTRACT, dict) else None,
            tool=name,
            target=compact_text(target if target is not None else "-", 180),
            reason=compact_text(issue, 420),
        )
    return issue


def _accepted_impact_contract_for_result(task, result):
    """Return only a controller-accepted artifact for post-mutation audit.

    Some long-standing architecture tests replace ``execute_agent_task`` with
    a deterministic leaf stub.  Those stubs predate the Impact Contract and
    intentionally return only the historical worker result shape.  The real
    Worker executor always emits ``impact_authorized`` and the accepted
    artifact; this helper keeps those test doubles from being mistaken for a
    forged authorization while preserving fail-closed behavior for the real
    seam.
    """

    for owner in (task, result):
        if not isinstance(owner, dict):
            continue
        candidate = owner.get("impact_contract")
        if (
            isinstance(candidate, dict)
            and candidate.get("controller_accepted") is True
            and candidate.get("status") == stage10_impact.IMPACT_ACCEPTED
        ):
            return candidate
    return None


def _impact_result_requires_artifact(result):
    """Identify a real Worker result that promised Impact Contract state."""

    return isinstance(result, dict) and (
        result.get("impact_required") is True
        or "impact_authorized" in result
        or "mutation_authorized" in result and "impact_contract" in result
    )


def _impact_tool_projection(tools, *, required=False):
    if not required:
        return list(tools or [])
    if stage10_impact.impact_mutation_block_reason(
        ACTIVE_IMPACT_CONTRACT, required=True,
        world_model=_world_model_for_workspace(),
    ):
        return [
            item for item in list(tools or [])
            if item.get("function", {}).get("name") not in _CONTEXT_MUTATION_TOOLS
        ]
    return list(tools or [])


def _impact_contract_projection_text(task):
    candidate = None
    if isinstance(task, dict):
        candidate = task.get("impact_contract") or task.get("impact_contract_candidate")
    if not isinstance(candidate, dict):
        return ""
    try:
        projection = stage10_impact.project_impact_contract(
            candidate, max_chars=stage10_impact.MAX_IMPACT_PROJECTION_CHARS,
        )
        rendered = projection.get("rendered", "")
        return compact_text(rendered, stage10_impact.MAX_IMPACT_PROJECTION_CHARS)
    except Exception:
        return ""


def _impact_post_mutation_check(contract, *, verification_result=None,
                                verification_evidence=None, changed_paths=None,
                                task_id="ROOT", task=None):
    """Compare the current transaction to the accepted impact contract."""
    if not isinstance(contract, dict):
        return {"status": stage10_impact.IMPACT_REQUIRED, "passed": False,
                "failure_type": stage10_impact.IMPACT_REQUIRED}
    transaction = ACTIVE_TRANSACTION or LAST_COMMITTED_TRANSACTION
    revalidation_paths = list(changed_paths or [])
    if not revalidation_paths and isinstance(transaction, dict):
        revalidation_paths = list((transaction.get("files") or {}).keys())
    model = _world_model_for_workspace()
    # Impact comparison runs before commit so an unsafe change can still be
    # rolled back.  Revalidate the bounded changed surface first; otherwise a
    # relationship delta would be compared against the pre-mutation World
    # Model and a valid post-state could never satisfy the contract.
    if model is not None and revalidation_paths:
        _world_model_revalidate_after_files(
            revalidation_paths[:stage10_impact.MAX_IMPACT_CHANGED_PATHS],
            phase="impact_precommit",
        )
        model = _world_model_for_workspace()
    actual = stage10_impact.capture_actual_mutation_impact(
        transaction=transaction,
        workspace=WORKSPACE,
        world_model=model,
        changed_paths=changed_paths,
        verification_evidence=verification_evidence,
    )
    comparison = stage10_impact.compare_pre_mutation_impact(
        contract, actual,
        world_model=model,
        verification_result=verification_result,
    )
    # One bounded related-surface revision is allowed for a genuinely related
    # file.  A new unrelated file remains an immediate out-of-scope failure.
    if comparison.get("unexpected_related"):
        discovered = [
            {"target": item.get("path"), "path": item.get("path"), "kind": "path",
             "provenance": [{"path": item.get("path"), "location": "post-mutation", "evidence_kind": "mutation_audit"}]}
            for item in comparison.get("unexpected_related", [])[:stage10_impact.MAX_IMPACT_CHANGED_PATHS]
        ]
        revised = stage10_impact.revise_pre_mutation_impact_contract(
            contract, discovered, world_model=model,
            reason="bounded related mutation surface observed by the controller",
        )
        if revised.get("revised"):
            accepted = stage10_impact.accept_pre_mutation_impact_contract(
                revised.get("contract"), world_model=model,
            )
            if accepted.get("accepted"):
                contract = accepted["contract"]
                if isinstance(task, dict):
                    task["impact_contract"] = copy.deepcopy(contract)
                    task["impact_contract_revision"] = contract.get("revision", 0)
                comparison = stage10_impact.compare_pre_mutation_impact(
                    contract, actual, world_model=model,
                    verification_result=verification_result,
                )
                _impact_record_metrics(revised=True)
                record_run_event(
                    "impact_contract_revised",
                    task_id=task_id,
                    revision=contract.get("revision", 0),
                    added_targets=[item.get("target") for item in revised.get("added_targets", [])],
                )
    _impact_record_metrics(comparison=comparison)
    record_run_event(
        "impact_contract_compared",
        task_id=task_id,
        status=comparison.get("status"),
        changed_paths=list(comparison.get("actual_changed_paths", []) or [])[:stage10_impact.MAX_IMPACT_CHANGED_PATHS],
        missing=len(comparison.get("missing", []) or []),
        unexpected_related=len(comparison.get("unexpected_related", []) or []),
        out_of_scope=len(comparison.get("out_of_scope", []) or []),
        preservation_violations=len(comparison.get("preservation_violations", []) or []),
        mutation_authorized=bool(comparison.get("passed")),
    )
    return comparison


def _prepare_task_impact_contract(task, contract=None):
    """Build the bounded candidate before the Worker context is compiled."""
    if not isinstance(task, dict):
        return None
    effective = _impact_effective_contract(contract)
    explicit = task.get("impact_contract_candidate")
    mutation_required = not bool(task.get("verification_only"))
    if isinstance(effective, dict) and "worker_required" in effective:
        mutation_required = bool(effective.get("worker_required"))
    candidate = _impact_candidate_for_worker(
        task.get("goal", ""), task.get("id", "ROOT"),
        candidate=explicit,
        context_anchor={
            "root_goal": ((RUN.get("source_contract") or {}).get("goal")
                          if isinstance(RUN.get("source_contract"), dict) else None)
            or task.get("root_goal") or task.get("goal"),
            "parent_goal": task.get("parent_goal") or RUN.get("parent_goal"),
            "local_task": task.get("goal"),
            "group_goal": task.get("semantic_group_goal"),
            "group_invariant": task.get("semantic_group_invariant"),
            "requirements": task.get("done_when", []),
            "constraints": (contract or {}).get("constraints", []) if isinstance(contract, dict) else [],
        },
        execution_contract=effective,
        mutation_required=mutation_required,
    )
    task["impact_contract_candidate"] = copy.deepcopy(candidate)
    task["impact_contract_status"] = stage10_impact.IMPACT_INCOMPLETE
    task["impact_contract_hash"] = candidate.get("contract_hash")
    task["impact_contract_revision"] = candidate.get("revision", 0)
    task["impact_contract_required"] = mutation_required
    _impact_record_metrics(created=True)
    record_run_event(
        "impact_contract_created",
        task_id=task.get("id"),
        contract_id=candidate.get("contract_id"),
        contract_hash=candidate.get("contract_hash"),
        target_count=len(candidate.get("expected_targets", []) or []),
        obligation_count=len(candidate.get("verification_obligations", []) or []),
        mutation_required=mutation_required,
    )
    return candidate


def _context_anchor_for_worker(task_text, task_id, context_anchor=None, execution_contract=None):
    """Construct the stable goal hierarchy from existing authority fields."""
    supplied = copy.deepcopy(context_anchor) if isinstance(context_anchor, dict) else {}
    active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
    contract = execution_contract if isinstance(execution_contract, dict) else {}
    nested = contract.get("execution_contract") if isinstance(contract.get("execution_contract"), dict) else {}
    effective = nested or contract
    source = RUN.get("source_contract") if isinstance(RUN.get("source_contract"), dict) else {}
    supplied.setdefault("root_goal", source.get("goal") or supplied.get("goal") or effective.get("goal"))
    supplied.setdefault("parent_goal", active.get("parent_goal") or RUN.get("parent_goal"))
    supplied.setdefault("local_task", task_text)
    supplied.setdefault(
        "requirements",
        active.get("requirements") or effective.get("requirements") or effective.get("done_when"),
    )
    supplied.setdefault(
        "constraints",
        active.get("constraints") or effective.get("constraints") or effective.get("local_preservation_constraints"),
    )
    supplied.setdefault(
        "allowed_inspection_paths",
        active.get("allowed_inspection_paths") or effective.get("allowed_inspection_paths"),
    )
    supplied["task_id"] = str(task_id)
    return supplied


def _context_initial_evidence(execution_contract=None, initial_context_evidence=None, task_text=None):
    if initial_context_evidence is not None:
        if isinstance(initial_context_evidence, dict):
            evidence = [initial_context_evidence]
        else:
            evidence = list(initial_context_evidence or [])
    else:
        contract = execution_contract if isinstance(execution_contract, dict) else {}
        nested = contract.get("execution_contract") if isinstance(contract.get("execution_contract"), dict) else {}
        effective = nested or contract
        facts = effective.get("relevant_repository_facts")
        evidence = list(facts) if isinstance(facts, list) else []
    # Supplement the existing Stage 4 evidence packet only when a compact,
    # complete, current semantic slot is already known.  This is not a global
    # model dump and it never replaces the goal/task anchor.
    model = _world_model_for_workspace()
    if model is not None and task_text:
        try:
            available_items = max(0, MAX_CONTEXT_EVIDENCE_ITEMS - len(evidence))
            if not available_items:
                return evidence
            contract = execution_contract if isinstance(execution_contract, dict) else {}
            nested = contract.get("execution_contract") if isinstance(contract.get("execution_contract"), dict) else {}
            allowed_paths = nested.get("allowed_inspection_paths")
            if allowed_paths is None:
                allowed_paths = contract.get("allowed_inspection_paths")
            if allowed_paths is None:
                allowed_paths = (ACTIVE_TOOL_CONTRACT or {}).get("allowed_inspection_paths")
            model_evidence = model.evidence_for_task(
                task_text,
                max_facts=min(available_items, stage8_world.MAX_WORLD_MODEL_PROJECTION_FACTS),
                allowed_paths=allowed_paths,
            )
            # Keep the initial packet authoritative and within the gate's
            # existing serialized evidence budget.  The model is a small
            # supplement; it never evicts Stage 4 items to make room.
            for item in model_evidence:
                candidate = evidence + [item]
                if len(json.dumps(candidate, ensure_ascii=False, default=str)) > MAX_CONTEXT_EVIDENCE_CHARS:
                    break
                evidence.append(item)
            _sync_world_model_metrics(model)
        except Exception:
            pass
    return evidence


def _context_gate_for_execution(
    task_text,
    task_id,
    *,
    enabled=False,
    gate=None,
    provider=None,
    anchor=None,
    execution_contract=None,
    initial_context_evidence=None,
):
    if not enabled and gate is None:
        return None
    if isinstance(gate, stage7_context.ContextSufficiencyGate):
        return gate
    return stage7_context.ContextSufficiencyGate(
        _context_anchor_for_worker(task_text, task_id, anchor, execution_contract),
        initial_evidence=_context_initial_evidence(
            execution_contract, initial_context_evidence, task_text=task_text,
        ),
        evidence_provider=provider or _provide_targeted_context_evidence,
    )


def _record_context_sufficiency_result(task_id, role, result, *, initial=False):
    """Record gate identifiers and decisions, never source blobs."""
    if not isinstance(result, dict):
        return
    if initial:
        RUN["context_sufficiency_initial_packets"] = RUN.get("context_sufficiency_initial_packets", 0) + 1
    else:
        RUN["context_sufficiency_checks"] = RUN.get("context_sufficiency_checks", 0) + 1
    round_number = int(result.get("round", 0) or 0)
    gate = _active_context_gate(role)
    last_logged = getattr(gate, "_mini_last_logged_round", 0) if gate is not None else 0
    if round_number > last_logged:
        RUN["context_completion_rounds"] = RUN.get("context_completion_rounds", 0) + (round_number - last_logged)
        if gate is not None:
            setattr(gate, "_mini_last_logged_round", round_number)
    requests = result.get("needed_evidence", []) if isinstance(result.get("needed_evidence"), list) else []
    returned = result.get("evidence", []) if isinstance(result.get("evidence"), list) else []
    semantic_resolutions = [
        item for item in result.get("semantic_resolutions", []) or []
        if isinstance(item, dict)
    ]
    RUN["context_evidence_requests"] = RUN.get("context_evidence_requests", 0) + len(requests)
    RUN["context_evidence_items"] = RUN.get("context_evidence_items", 0) + len(returned)
    RUN["semantic_evidence_items"] = RUN.get("semantic_evidence_items", 0) + len(returned)
    RUN["context_contradictions"] = max(
        RUN.get("context_contradictions", 0),
        len(result.get("contradictions", []) or []),
    )
    for resolution in semantic_resolutions:
        status = str(resolution.get("resolution_status") or "")
        if status in {"resolved", "partial", "unresolved", "conflicting"}:
            counter_key = (
                "semantic_evidence_conflicts"
                if status == "conflicting"
                else "semantic_evidence_" + status
            )
            RUN[counter_key] = RUN.get(counter_key, 0) + 1
        RUN["semantic_evidence_candidates"] = RUN.get("semantic_evidence_candidates", 0) + int(
            resolution.get("candidates_considered", 0) or 0
        )
        RUN["semantic_evidence_hops"] = RUN.get("semantic_evidence_hops", 0) + int(
            resolution.get("relationship_hops", 0) or 0
        )
    RUN["semantic_evidence_requests"] = RUN.get("semantic_evidence_requests", 0) + len(
        semantic_resolutions
    )
    if result.get("mutation_allowed") and gate is not None and not getattr(gate, "_mini_authorization_logged", False):
        RUN["context_mutation_authorizations"] = RUN.get("context_mutation_authorizations", 0) + 1
        setattr(gate, "_mini_authorization_logged", True)
    record_run_event(
        "context_sufficiency_initial_context" if initial else "context_sufficiency_decision",
        role=role,
        task_id=str(task_id),
        lifecycle_state=result.get("lifecycle_state") or result.get("state"),
        context_status=result.get("context_status"),
        round=round_number,
        max_rounds=result.get("max_rounds"),
        request_count=result.get("request_count"),
        request_kinds=sorted({str(item.get("kind")) for item in requests if isinstance(item, dict)}),
        request_targets=[compact_text(item.get("target"), 180) for item in requests if isinstance(item, dict)][:MAX_EVIDENCE_REQUESTS_PER_ROUND],
        returned_evidence_count=len(returned),
        working_evidence_count=result.get("working_evidence_count"),
        working_evidence_chars=result.get("working_evidence_chars"),
        initial_context_chars=result.get("initial_context_chars"),
        anchor_hash=result.get("anchor_hash"),
        contradictions=len(result.get("contradictions", []) or []),
        semantic_resolution_statuses=sorted({
            str(item.get("resolution_status"))
            for item in semantic_resolutions
            if item.get("resolution_status")
        }),
        semantic_request_kinds=sorted({
            str(item.get("request_kind"))
            for item in semantic_resolutions
            if item.get("request_kind")
        }),
        semantic_resolution_count=len(semantic_resolutions),
        mutation_authorized=bool(result.get("mutation_allowed")),
        final=bool(result.get("final")),
        failure_code=result.get("failure_code"),
        reason=compact_text(result.get("reason"), 420),
    )


def _context_evidence_feedback(result):
    """Return a small re-evaluation packet containing only new evidence."""
    value = result if isinstance(result, dict) else {}
    lines = [stage7_context.feedback_for_result(value)]
    for resolution in list(value.get("semantic_resolutions", []) or [])[:stage7_context.MAX_CONTEXT_SEMANTIC_RESOLUTIONS]:
        if not isinstance(resolution, dict):
            continue
        facts = "; ".join(
            compact_text(item, stage7_context.MAX_CONTEXT_EVIDENCE_FACT_CHARS)
            for item in list(resolution.get("facts_established", []) or [])[:2]
        )
        lines.append(
            f"SEMANTIC RESOLUTION [{resolution.get('request_kind', 'unknown')}] "
            f"{resolution.get('target', 'unknown')}: "
            f"{resolution.get('resolution_status', 'unknown')}"
            + (f" | facts: {facts}" if facts else "")
        )
    for item in list(value.get("evidence", []) or [])[:MAX_EVIDENCE_REQUESTS_PER_ROUND * 2]:
        if not isinstance(item, dict):
            continue
        identity = item.get("source_identity") or item.get("evidence_id") or "unknown-source"
        purpose = compact_text(item.get("purpose", ""), 260)
        excerpt = compact_text(item.get("excerpt", ""), stage7_context.MAX_CONTEXT_EVIDENCE_ITEM_CHARS)
        lines.append(
            f"TARGETED EVIDENCE [{item.get('kind', 'evidence')}] {identity}"
            + (f" ({purpose})" if purpose else "")
            + (f":\n{excerpt}" if excerpt else "")
        )
    return "\n".join(lines)


def _context_result_json(result):
    """Keep the structured tool result compact and valid JSON."""
    value = dict(result or {})
    value["evidence"] = list(value.get("evidence", []) or [])[:MAX_EVIDENCE_REQUESTS_PER_ROUND * 2]
    value["history"] = None
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)


def _context_sufficiency_failed(result):
    """Identify a bounded context stop before verification/recovery routing."""
    if not isinstance(result, dict):
        return False
    if result.get("failure_type") == CONTEXT_INSUFFICIENT_FAILURE:
        return True
    snapshot = result.get("context_sufficiency")
    return isinstance(snapshot, dict) and snapshot.get("failure_code") == CONTEXT_INSUFFICIENT_FAILURE


def _context_sufficiency_tool(args, role="System", task_id="ROOT"):
    gate = _active_context_gate(role)
    if gate is None:
        return "error: context_sufficiency_check is available only during a gated Worker attempt"
    checked = stage7_context.validate_sufficiency_decision(args if isinstance(args, dict) else {})
    if not checked.get("valid"):
        result = {
            "context_status": stage7_context.CONTEXT_STATUS_INSUFFICIENT,
            "lifecycle_state": stage7_context.PREPARING_CONTEXT,
            "mutation_allowed": False,
            "reason": "Invalid structured sufficiency decision; submit the bounded schema again.",
            "errors": checked.get("errors", [])[:12],
            "failure_code": None,
            "final": False,
        }
    else:
        result = gate.evaluate(args)
    _record_context_sufficiency_result(task_id, role, result)
    return _context_result_json(result)


def _context_candidate_files(request, context):
    """Resolve only files named by the current bounded inspection surface."""
    if WORKSPACE is None:
        return []
    allowed = list((context or {}).get("allowed_inspection_paths", []) or [])
    candidates = []
    seen = set()
    for raw in allowed:
        target = safe_path(raw)
        if target is None or not target.exists():
            continue
        if target.is_file():
            files = [target]
        elif target.is_dir():
            try:
                files = [
                    item for item in target.rglob("*")
                    if item.is_file()
                    and item.suffix.casefold() in _CONTEXT_SOURCE_EXTENSIONS
                    and not any(part in {".git", ".venv", "node_modules", "__pycache__"} for part in item.parts)
                ]
            except OSError:
                files = []
        else:
            files = []
        for item in files:
            resolved = item.resolve()
            if not resolved.is_relative_to(Path(WORKSPACE).resolve()):
                continue
            key = str(resolved).casefold()
            if key not in seen:
                seen.add(key)
                candidates.append(resolved)
    target_text = str((request or {}).get("target", "")).casefold()
    kind = str((request or {}).get("kind", "")).casefold()
    def score(path):
        name = path.name.casefold()
        text = str(path).casefold()
        score_value = 0
        if target_text and target_text in text:
            score_value += 8
        if kind == "tests" or kind in {"callers", "consumers", "return_expectation"}:
            if "test" in name or "spec" in name:
                score_value += 6
        if kind in {"contract", "authoritative_contract", "interface", "schema", "definition"}:
            if any(word in name for word in ("contract", "interface", "schema", "type", "api")):
                score_value += 5
        if kind == "sibling_implementation" and "test" not in name:
            score_value += 2
        return (-score_value, len(str(path)), str(path).casefold())
    return sorted(candidates, key=score)[:_CONTEXT_PROVIDER_MAX_FILES]


def _world_model_for_workspace(workspace=None, repository_map=None):
    """Return the one bounded semantic model for the current project/run."""
    global ACTIVE_PROJECT_WORLD_MODEL
    root_value = workspace if workspace is not None else WORKSPACE
    if root_value is None:
        return None
    try:
        root = Path(root_value).expanduser().resolve()
        if not root.is_dir():
            return None
    except (OSError, RuntimeError, TypeError, ValueError):
        return None
    project_id = None
    if isinstance(RUN, dict):
        project_id = RUN.get("project_id") or RUN.get("workspace_id") or RUN.get("repository_id")
    if not isinstance(ACTIVE_PROJECT_WORLD_MODEL, stage8_world.ProjectWorldModel):
        ACTIVE_PROJECT_WORLD_MODEL = stage8_world.ProjectWorldModel(
            root, project_id=project_id, repository_map=repository_map,
        )
        if isinstance(RUN, dict):
            RUN["world_model_project_identity"] = ACTIVE_PROJECT_WORLD_MODEL.project_identity
        record_run_event(
            "world_model_initialized",
            project_identity=ACTIVE_PROJECT_WORLD_MODEL.project_identity,
            fact_count=0,
        )
    elif not ACTIVE_PROJECT_WORLD_MODEL.matches_project(root, project_id):
        previous = ACTIVE_PROJECT_WORLD_MODEL.project_identity
        ACTIVE_PROJECT_WORLD_MODEL = stage8_world.ProjectWorldModel(
            root, project_id=project_id, repository_map=repository_map,
        )
        if isinstance(RUN, dict):
            RUN["world_model_project_identity"] = ACTIVE_PROJECT_WORLD_MODEL.project_identity
        record_run_event(
            "world_model_project_switched",
            previous_project_identity=previous,
            project_identity=ACTIVE_PROJECT_WORLD_MODEL.project_identity,
        )
    else:
        ACTIVE_PROJECT_WORLD_MODEL.attach_repository_map(repository_map)
    return ACTIVE_PROJECT_WORLD_MODEL


def _sync_world_model_metrics(model):
    if not isinstance(model, stage8_world.ProjectWorldModel) or not isinstance(RUN, dict):
        return
    stats = model.stats
    RUN["world_model_facts_stored"] = int(stats.get("facts_stored", 0))
    RUN["world_model_facts_reused"] = int(stats.get("facts_reused", 0))
    RUN["world_model_fact_invalidations"] = int(stats.get("facts_invalidated", 0))
    RUN["world_model_facts_stale"] = int(stats.get("facts_stale", 0))
    RUN["world_model_revalidations"] = int(stats.get("facts_revalidated", 0))
    RUN["world_model_rejected_facts"] = int(stats.get("facts_rejected", 0))
    RUN["world_model_conflicts"] = int(stats.get("conflicts", 0))
    RUN["world_model_projections"] = int(stats.get("projections", 0))
    RUN["world_model_projection_facts"] = int(stats.get("projection_facts", 0))
    RUN["world_model_project_identity"] = model.project_identity


def _world_model_invalidate_paths(paths, *, phase="mutation"):
    model = _world_model_for_workspace()
    if model is None:
        return []
    invalidated = model.invalidate_paths(paths)
    _sync_world_model_metrics(model)
    if invalidated:
        record_run_event(
            "world_model_facts_invalidated",
            phase=phase,
            project_identity=model.project_identity,
            fact_count=len(invalidated),
            fact_ids=invalidated[:stage8_world.MAX_WORLD_MODEL_FACTS_PER_PROJECTION],
            paths=[str(path) for path in list(paths or [])[:8]],
        )
    return invalidated


def _world_model_revalidate_after_files(changed_paths, *, phase="commit"):
    """Revalidate only stale facts touching the bounded mutation surface."""
    model = _world_model_for_workspace()
    if model is None:
        return {"revalidated": [], "targets": []}
    paths = list(changed_paths or [])
    if phase == "rollback":
        # A Worker may have resolved the post-mutation source before
        # verification failed.  Stale every current fact on the restored
        # path first, then restore only facts whose original fingerprint is
        # back; post-mutation facts therefore cannot become ghost VERIFIED
        # facts after rollback.
        model.invalidate_paths(paths)
        revalidated = model.restore_paths(paths)
        _sync_world_model_metrics(model)
        if revalidated:
            record_run_event(
                "world_model_rollback_revalidated",
                project_identity=model.project_identity,
                fact_count=len(revalidated),
                fact_ids=revalidated[:stage8_world.MAX_WORLD_MODEL_FACTS_PER_PROJECTION],
            )
        return {"revalidated": revalidated, "targets": []}

    if model.repository_map is not None:
        try:
            updated_map = core1_repository_map.incremental_reindex(
                model.repository_map,
                model.project_root,
                changed_paths=paths,
                metrics=None,
            )
            model.attach_repository_map(updated_map)
        except (OSError, RuntimeError, TypeError, ValueError):
            pass
    # A fact may have been re-added while the transaction was open.  Force
    # every source-dependent fact on the committed path through the bounded
    # revalidation list so success is based on post-mutation evidence.
    model.invalidate_paths(paths)
    targets = model.revalidation_targets(paths)[:stage8_world.MAX_WORLD_MODEL_REVALIDATION_TARGETS]
    results = []
    for target in targets:
        kind = target.get("semantic_kind") or "SYMBOL_DEFINITION"
        request = {
            "kind": kind,
            "target": target.get("target", ""),
            "why": "Revalidate the affected semantic fact against the post-mutation source before reuse.",
        }
        try:
            resolver = stage7_semantic.SemanticEvidenceResolver(
                model.project_root,
                [model.project_root],
                repository_map=model.repository_map,
                world_model=model,
                max_relationship_hops=stage7_semantic.MAX_RELATIONSHIP_HOPS,
                max_candidates=stage7_semantic.MAX_CANDIDATES_PER_REQUEST,
                max_files_scanned=_CONTEXT_PROVIDER_MAX_FILES,
                max_evidence_items=_CONTEXT_PROVIDER_MAX_EXCERPTS_PER_REQUEST,
            )
            result = resolver.resolve(request)
            results.append({
                "target": compact_text(target.get("target"), 180),
                "relation": target.get("relation"),
                "resolution_status": result.get("resolution_status"),
                "source_scan_performed": bool(result.get("source_scan_performed")),
            })
            if isinstance(RUN, dict) and result.get("source_scan_performed"):
                RUN["world_model_source_scans"] = RUN.get("world_model_source_scans", 0) + 1
        except Exception as exc:
            results.append({
                "target": compact_text(target.get("target"), 180),
                "relation": target.get("relation"),
                "resolution_status": "revalidation_error",
                "error": compact_text(str(exc), 180),
            })
    model.refresh_currentness()
    _sync_world_model_metrics(model)
    record_run_event(
        "world_model_revalidation",
        phase=phase,
        project_identity=model.project_identity,
        target_count=len(targets),
        results=results[:stage8_world.MAX_WORLD_MODEL_REVALIDATION_TARGETS],
    )
    return {"revalidated": [item for item in results if item.get("resolution_status") == "resolved"], "targets": results}


def _provide_targeted_context_evidence(request, context):
    """Resolve one validated request into a bounded semantic evidence bundle."""
    request = request if isinstance(request, dict) else {}
    checked = stage7_context.validate_evidence_request(request)
    if not checked.get("valid") or not checked.get("request"):
        return {
            "request_kind": str(request.get("kind", "")),
            "target": str(request.get("target", "")),
            "resolution_status": "unresolved",
            "facts_established": [],
            "evidence": [],
            "resolver": "SEMANTIC_EVIDENCE_RESOLVER",
        }
    if WORKSPACE is None:
        return {
            "request_kind": checked["request"].get("kind", ""),
            "target": checked["request"].get("target", ""),
            "resolution_status": "unresolved",
            "facts_established": [],
            "evidence": [],
            "resolver": "SEMANTIC_EVIDENCE_RESOLVER",
        }
    repository_map = RUN.get("repository_map") if isinstance(RUN, dict) else None
    world_model = _world_model_for_workspace(WORKSPACE, repository_map=repository_map)
    result = stage7_semantic.resolve_targeted_evidence(
        checked["request"],
        workspace=WORKSPACE,
        allowed_inspection_paths=(context or {}).get("allowed_inspection_paths", []),
        repository_map=repository_map,
        context=context,
        max_relationship_hops=stage7_semantic.MAX_RELATIONSHIP_HOPS,
        max_candidates=stage7_semantic.MAX_CANDIDATES_PER_REQUEST,
        # Retain the previous inspection-surface file bound and the previous
        # two-excerpt provider slot; semantic selection decides which two are
        # authoritative instead of lexical order deciding it.
        max_files_scanned=_CONTEXT_PROVIDER_MAX_FILES,
        max_evidence_items=_CONTEXT_PROVIDER_MAX_EXCERPTS_PER_REQUEST,
        world_model=world_model,
    )
    if isinstance(RUN, dict):
        RUN["world_model_source_scans"] = RUN.get("world_model_source_scans", 0) + int(
            bool(result.get("source_scan_performed"))
        )
    _sync_world_model_metrics(world_model)
    record_run_event(
        "world_model_evidence_resolution",
        project_identity=(world_model.project_identity if world_model is not None else None),
        request_kind=result.get("request_kind"),
        target=compact_text(result.get("target"), 180),
        resolution_status=result.get("resolution_status"),
        reused=bool(result.get("world_model_reused")),
        source_scan_performed=bool(result.get("source_scan_performed")),
        evidence_count=len(result.get("evidence", []) or []),
    )
    return result


def _normalized_workspace_relative_path(raw_path):
    target = safe_path(raw_path)
    if target is None or WORKSPACE is None:
        return None
    try:
        return target.relative_to(Path(WORKSPACE).resolve()).as_posix().casefold()
    except (OSError, RuntimeError, ValueError):
        return None


def _stage3_mutation_guard(name, args):
    if name not in {"write_file", "edit_file", "edit_file_range"}:
        return None
    if RUN.get("stage6c_enabled"):
        authority_gate = stage6c.worker_authorization_gate(
            RUN.get("execution_authorization"),
            RUN.get("approval_receipt"),
            RUN.get("pre_execution_approval_revalidation"),
            request=RUN.get("approval_request"),
            verification_obligation_coverage=RUN.get("verification_obligation_coverage"),
        )
        if not authority_gate.get("allowed"):
            return (
                f"error: {authority_gate.get('code') or EXECUTION_AUTHORIZATION_BLOCKED}; "
                "Stage 6C-A has no exact current execution authorization"
            )
        active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
        effective = _current_execution_contract(active) if active.get("execution_contract_id") else None
        if not isinstance(effective, dict):
            return (
                f"error: {EXECUTION_AUTHORIZATION_BLOCKED}; "
                "Stage 6C-A stops before a mutable Worker contract is activated"
            )
        target = _normalized_workspace_relative_path((args or {}).get("path"))
        check = stage4.tool_scope(effective, target, mutation=True)
        if not check.get("allowed"):
            RUN["approval_contract_binding_failures"] = RUN.get("approval_contract_binding_failures", 0) + 1
            return (
                f"error: {stage6c.APPROVAL_MUTATION_SCOPE_MISMATCH}; "
                f"'{(args or {}).get('path')}' is outside the approval-bound contract"
            )
        return None
    if not RUN.get("impact_planning_required") or RUN.get("project_mode") != EXISTING_PROJECT:
        return None
    plan = RUN.get("approved_change_plan")
    approval = RUN.get("plan_approval")
    active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
    if active.get("execution_contract_id"):
        effective = _current_execution_contract(active)
        if not isinstance(effective, dict):
            RUN["execution_contract_stale_blocks"] = RUN.get(
                "execution_contract_stale_blocks", 0,
            ) + 1
            return f"error: {APPROVED_PLAN_STALE}; active execution contract is stale or unavailable"
        target = _normalized_workspace_relative_path((args or {}).get("path"))
        check = stage4.tool_scope(effective, target, mutation=True)
        if not check.get("allowed"):
            RUN["execution_contract_scope_violations"] = RUN.get(
                "execution_contract_scope_violations", 0,
            ) + 1
            record_run_event(
                "execution_contract_scope_violation",
                execution_contract_id=effective.get("execution_contract_id"),
                path=target, reason=check.get("reason"),
            )
            return (
                f"error: {CONTRACT_SCOPE_VIOLATION}; '{(args or {}).get('path')}' "
                "is outside the approved execution-contract mutation scope"
            )
        return None
    if not stage3.approval_is_current(plan, approval):
        return (
            f"error: {PLAN_APPROVAL_REQUIRED}; existing-project mutation is read-only "
            "until the current plan hash is approved"
        )
    if active.get("approved_plan_hash") != plan.get("plan_hash"):
        return f"error: {PLAN_APPROVAL_REQUIRED}; active Worker plan hash is stale"
    target = _normalized_workspace_relative_path((args or {}).get("path"))
    approved = {
        str(item).replace("\\", "/").casefold()
        for item in active.get("approved_targets", []) or []
    }
    inspect_only = {
        str(item).replace("\\", "/").casefold()
        for item in active.get("inspect_only_targets", []) or []
    }
    do_not_touch = {
        str(item).replace("\\", "/").casefold()
        for item in active.get("do_not_touch", []) or []
    }
    if (
        target is None or active.get("verification_only")
        or target in do_not_touch or target in inspect_only or target not in approved
    ):
        RUN["unapproved_scope_expansions"] = RUN.get("unapproved_scope_expansions", 0) + 1
        record_run_event(
            "unapproved_scope_expansion", target=target,
            approved_targets=sorted(approved), inspect_only_targets=sorted(inspect_only),
            do_not_touch=sorted(do_not_touch), plan_id=plan.get("plan_id"),
        )
        return (
            f"error: {UNAPPROVED_SCOPE_EXPANSION}; '{(args or {}).get('path')}' "
            "is not an approved mutation target for this plan node"
        )
    return None


def _stage4_inspection_guard(name, args):
    """Keep Worker reads inside the current contract's inspection surface."""
    if name not in {"read_file", "read_file_range"}:
        return None
    active = ACTIVE_TOOL_CONTRACT if isinstance(ACTIVE_TOOL_CONTRACT, dict) else {}
    if not active.get("execution_contract_id"):
        return None
    effective = _current_execution_contract(active)
    if not isinstance(effective, dict):
        RUN["execution_contract_stale_blocks"] = RUN.get(
            "execution_contract_stale_blocks", 0,
        ) + 1
        return f"error: {APPROVED_PLAN_STALE}; active execution contract is stale or unavailable"
    target = _normalized_workspace_relative_path((args or {}).get("path"))
    check = stage4.tool_scope(effective, target, mutation=False)
    if check.get("allowed"):
        return None
    RUN["execution_contract_scope_violations"] = RUN.get(
        "execution_contract_scope_violations", 0,
    ) + 1
    record_run_event(
        "execution_contract_inspection_violation",
        execution_contract_id=effective.get("execution_contract_id"),
        path=target, reason=check.get("reason"),
    )
    return (
        f"error: {CONTRACT_SCOPE_VIOLATION}; '{(args or {}).get('path')}' "
        "is outside the approved execution-contract inspection scope"
    )


def run_tool(name, args, role="System"):
    if role == "Falsifier" and name in {"write_file", "edit_file", "edit_file_range", "backup_file"}:
        return "error: Falsifier is read-only and may not modify files"
    if role == "Repairer" and name in {"write_file", "backup_file"}:
        return "error: Repairer may only make focused edits"
    issue = tool_argument_error(name, args)
    if issue:
        return issue
    context_mutation_issue = _context_gate_mutation_guard(
        name, role=role, target=(args or {}).get("path") if isinstance(args, dict) else None,
    )
    if context_mutation_issue:
        return context_mutation_issue
    impact_mutation_issue = _impact_gate_mutation_guard(
        name, role=role, target=(args or {}).get("path") if isinstance(args, dict) else None,
    )
    if impact_mutation_issue:
        return impact_mutation_issue
    if name == _CONTEXT_COMPLETION_TOOL:
        return _context_sufficiency_tool(args, role=role, task_id=(ACTIVE_TOOL_CONTRACT or {}).get("task_id", "ROOT"))
    stage4_inspection_issue = _stage4_inspection_guard(name, args)
    if stage4_inspection_issue:
        return stage4_inspection_issue
    stage3_issue = _stage3_mutation_guard(name, args)
    if stage3_issue:
        return stage3_issue
    if name == "write_file":
        return write_file(args["path"], args["content"], role=role)
    if name == "edit_file":
        return edit_file(args["path"], args["old"], args["new"], args.get("expected_replacements", 1))
    if name == "read_file_range":
        return read_file_range(args["path"], args.get("start_line", 1), args.get("end_line"))
    if name == "edit_file_range":
        return edit_file_range(args["path"], args["start_line"], args["end_line"], args["new"], role=role)
    if name == "read_file":
        return read_file(args["path"])
    if name == "backup_file":
        return backup_file(args["path"])
    if name == "list_files":
        return list_files()
    if name == "run_file":
        return run_file(args["path"])
    if name == "run_command":
        return run_command(args["command"])
    if name == "verify_web_app":
        active = ACTIVE_TOOL_CONTRACT or ACTIVE_CONTRACT or {}
        route_artifact = analyze_verification_applicability(
            active, active, requested_path=args.get("path"),
        )
        if route_artifact is None:
            authority_failure = _authority_terminal_failure(active) or EXECUTION_CONTRACT_BLOCKED
            blocked = _authority_fail_closed_result(
                authority_failure,
                message="verification routing is blocked because current execution authority is invalid",
                task_id=str(active.get("task_id") or "tool"),
            )
            blocked.update({
                "passed": False,
                "environment_error": False,
                "failure_type": authority_failure,
                "verification_status": authority_failure,
            })
            return json.dumps(blocked, ensure_ascii=False)
        browser_route = _verification_route(route_artifact, BROWSER_VERIFICATION)
        if browser_route and not browser_route.get("applicable") and not browser_route.get("required"):
            skipped = _verification_skip_result(active, route_artifact, browser_route)
            skipped["verification_applicability"] = _update_verification_applicability_result(
                route_artifact, None, BROWSER_VERIFICATION, skipped,
            )
            return "[not_applicable] " + json.dumps(skipped, ensure_ascii=False)
        if browser_route and browser_route.get("required") and not browser_route.get("target"):
            unresolved = _verification_required_target_result(active, route_artifact, browser_route)
            unresolved["verification_applicability"] = _update_verification_applicability_result(
                route_artifact, None, BROWSER_VERIFICATION, unresolved,
            )
            return json.dumps(unresolved, ensure_ascii=False)
        profile = infer_web_profile(str(active.get("goal") or "web"), active)
        target_evidence = {
            "requested_from_node": args["path"],
            "project_invariants": active.get("project_invariants", RUN.get("project_invariants", [])),
        }
        result = verify_browser_application(
            args["path"], str(active.get("task_id") or "tool"),
            profile=profile, evidence=target_evidence,
        )
        if route_artifact is not None:
            result["verification_status"] = VERIFICATION_PASS if result.get("passed") else VERIFICATION_FAIL
            result["verification_route"] = copy.deepcopy(browser_route or {})
            result["verification_applicability"] = _update_verification_applicability_result(
                route_artifact, None, BROWSER_VERIFICATION, result,
            )
        return json.dumps(result, ensure_ascii=False)
    return f"unknown tool: {name}"


