def _active_stage3_requirements(contract):
    contract = contract if isinstance(contract, dict) else {}
    ledger = contract.get("source_requirement_ledger")
    records = ledger_requirements(ledger, include_confirmed=True)
    if records:
        return stage3.active_requirements(records)
    # Compatibility contracts used by deterministic architecture tests may
    # predate the Source Requirement Ledger.  Give them stable local IDs
    # without changing Stage 1 production semantics.
    values = list(contract.get("requirements", []) or [])
    return stage3.active_requirements([
        {
            "requirement_id": f"REQ-{index:03d}", "text": value,
            "provenance": USER_STATED, "status": "active",
        }
        for index, value in enumerate(values, 1) if str(value).strip()
    ])


def _authoritative_stage3_task_goal(contract, task_brain=None):
    value = contract if isinstance(contract, dict) else {}
    source_contract = value.get("source_contract")
    if isinstance(source_contract, dict):
        source_goal = source_contract.get("root_goal")
        if isinstance(source_goal, str) and source_goal:
            return source_goal
    for candidate in (value.get("original_goal"), value.get("goal")):
        if isinstance(candidate, str) and candidate.strip():
            return candidate.strip()
    brain_goal = (task_brain or {}).get("task_goal", "")
    if isinstance(brain_goal, dict):
        brain_goal = brain_goal.get("text", "")
    return str(brain_goal or "").strip()


def _impact_project_invariants(task_brain):
    values = []
    for item in list((task_brain or {}).get("relevant_project_brain_projection", []) or []):
        if isinstance(item, dict) and str(item.get("text", "")).strip():
            values.append(item.get("text"))
    return values[:8]


def _record_planning_role_packet(role_packet):
    """Record one exact role packet without rebuilding or re-rendering it."""
    packet = role_packet if isinstance(role_packet, dict) else {}
    role = str(packet.get("role") or "PlanningRole")
    RUN.setdefault("planning_role_packets", {})[role] = copy.deepcopy(packet)
    RUN["planning_role_packets_built"] = RUN.get("planning_role_packets_built", 0) + 1
    if packet.get("packet_complete"):
        RUN["planning_role_packets_complete"] = RUN.get("planning_role_packets_complete", 0) + 1
    dropped = list(packet.get("optional_items_dropped", []) or [])
    if dropped:
        RUN["planning_role_packets_optional_trimmed"] = RUN.get(
            "planning_role_packets_optional_trimmed", 0,
        ) + 1
    RUN["planning_role_optional_items_dropped"] = RUN.get(
        "planning_role_optional_items_dropped", 0,
    ) + len(dropped)
    mandatory_drops = list(packet.get("mandatory_drops", []) or [])
    RUN["planning_role_mandatory_items_dropped"] = RUN.get(
        "planning_role_mandatory_items_dropped", 0,
    ) + len(mandatory_drops)
    if packet.get("status") == stage3.PLANNING_PACKET_MANDATORY_OVERFLOW:
        RUN["planning_role_packets_mandatory_overflow"] = RUN.get(
            "planning_role_packets_mandatory_overflow", 0,
        ) + 1
    RUN["planning_role_max_rendered_chars"] = max(
        RUN.get("planning_role_max_rendered_chars", 0),
        int(packet.get("rendered_chars", 0) or 0),
    )
    core_metrics = packet.get("mandatory_core_metrics")
    if isinstance(core_metrics, dict):
        RUN["mandatory_planning_records_input"] = RUN.get(
            "mandatory_planning_records_input", 0,
        ) + int(core_metrics.get("mandatory_planning_records_input", 0) or 0)
        RUN["mandatory_semantic_units"] = RUN.get("mandatory_semantic_units", 0) + int(
            core_metrics.get("mandatory_semantic_units", 0) or 0
        )
        RUN["mandatory_semantic_units_deduplicated"] = RUN.get(
            "mandatory_semantic_units_deduplicated", 0,
        ) + int(core_metrics.get("mandatory_semantic_units_deduplicated", 0) or 0)
        RUN["mandatory_provenance_refs"] = RUN.get("mandatory_provenance_refs", 0) + int(
            core_metrics.get("mandatory_provenance_refs", 0) or 0
        )
        before_chars = packet.get("mandatory_model_chars_before_normalization")
        if before_chars is None:
            before_chars = core_metrics.get("mandatory_model_chars_before_normalization", 0)
        after_chars = packet.get("mandatory_model_chars_after_normalization")
        if after_chars is None:
            after_chars = core_metrics.get("mandatory_model_chars_after_normalization", 0)
        RUN["mandatory_model_chars_before_normalization"] = max(
            RUN.get("mandatory_model_chars_before_normalization", 0),
            int(before_chars or 0),
        )
        RUN["mandatory_model_chars_after_normalization"] = max(
            RUN.get("mandatory_model_chars_after_normalization", 0),
            int(after_chars or 0),
        )
        coverage = float(core_metrics.get("mandatory_semantic_coverage", 1.0) or 0.0)
        RUN["mandatory_semantic_coverage"] = min(
            float(RUN.get("mandatory_semantic_coverage", 1.0)), coverage,
        )
        RUN["planning_core_builds"] = RUN.get("planning_core_builds", 0) + 1
        RUN["planning_core_model_calls"] = RUN.get("planning_core_model_calls", 0) + int(
            core_metrics.get("planning_core_model_calls", 0) or 0
        )
    audit = {
        key: copy.deepcopy(value) for key, value in packet.items()
        if key not in {
            "payload", "rendered_packet", "exact_model_input", "base_rendered_packet",
            "mandatory_rendered_packet", "mandatory_serialized_payload",
        }
    }
    record_run_event("planning_role_packet_built", **audit)
    return packet


def _planning_provider_renderer(base_renderer, schema):
    """Return the exact role renderer used for the provider packet.

    Structured roles already send ``schema`` through Ollama's ``format``
    transport field.  It is therefore not appended to the model-facing
    packet a second time.  Keeping it out of this renderer removes a hidden
    post-audit suffix while preserving the provider's structured-output
    contract.
    """
    del schema

    def render(context):
        return base_renderer(context)

    return render


def _impact_planner_prompt(context):
    return f"""You are IMPACT PLANNER, a narrow read-only role in a weak-model coding orchestrator.
Propose one COMPLETE bounded semantic decision set for the deterministic impact slots in the packet below.
The orchestrator has already bound every existing slot to a canonical surface. For each known existing
impact, decide only its disposition: MUST_CHANGE, INTERFACE_REUSE, TEST_CHANGE, PRESERVATION_ONLY,
VERIFY_ONLY, or INSUFFICIENT_EVIDENCE. Return the impact_id, valid Source Requirement IDs, and a concise
action/reason. Optionally return canonical INTERFACE surface IDs to reuse, preservation promises, and
verification/test contracts. Do not author or infer paths, symbols, owners, repository evidence IDs, or
existing surface bindings. surface_id is unnecessary; if you return one it is non-authoritative and must
match the supplied seed. Relevant does not mean MUST_CHANGE. A preservation surface remains unmodified
unless requirements and evidence prove mutation necessary. If no existing surface can safely represent a
responsibility, emit a separate justified NEW_SURFACE_PROPOSAL rather than using a fake existing identity.
Do not write code, execute tests, decompose Workers, call tools, or reproduce
raw source. Return only the requested structured map.

COMPLETE CANONICAL PLANNING PACKET:
{json.dumps(context, ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)}"""


def _impact_decision_frame_prompt_v24_4_2(context):
    """Render the frozen pre-projection V24.4.2 frame for audit only."""
    return f"""You are IMPACT PLANNER, a bounded read-only role in a weak-model coding orchestrator.
The ImpactDecisionFrame below is authoritative and was constructed before this call.

WHAT IS FIXED:
- slot, seed, impact, surface, owner, interface, DNT, prohibition, preservation, and verification identity.

WHAT YOU MUST DECIDE:
- return exactly one choice for every slot;
- choose only an allowed decision and an allowed target;
- choose decisions sufficient to satisfy the listed active obligations according to
  the frame's capability mapping;
- provide a short reason_code and bounded_rationale.

WHAT YOU MUST NOT REPEAT OR CHANGE:
- do not return or rewrite preservation_promises, verification_contracts, DNT, prohibitions, owners,
  repository paths, repository evidence, seed IDs, impact IDs, or surface IDs;
- do not add a slot, omit a slot, duplicate a slot, invent a target, or migrate ownership unless the
  frame explicitly exposes AUTHORITY_CHANGE.

Return only {{"decisions":[{{"slot_id":"...","decision":"...","chosen_target":"...",
"reason_code":"...","bounded_rationale":"..."}}]}}. Do not write code, inspect files, call tools,
or reproduce raw source.

AUTHORITY-BOUND DECISION FRAME:
{json.dumps(context, ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)}"""


def _impact_decision_frame_prompt(context):
    """Render the V24.4.3 decision-relevant choice projection envelope."""
    return f"""You are IMPACT PLANNER, a bounded read-only role in a weak-model coding orchestrator.
The full ImpactDecisionFrame was constructed and validated before this call. The
DecisionRelevantImpactChoiceProjection below is a read-only model-facing projection;
the full frame remains authoritative for every downstream decision and contract.

WHAT IS FIXED:
- slot, seed, impact, surface, owner, interface, DNT, prohibition, preservation, and verification identity;
- inherited current-state obligations and shared constraint aliases.

WHAT YOU MUST DECIDE:
- return exactly one choice for every required choice slot listed in response_bounds;
- choose only an allowed decision and an allowed target;
- choose decisions sufficient to satisfy the listed active obligations according to
  the full frame's capability mapping;
- provide a short reason_code and bounded_rationale.

WHAT YOU MUST NOT REPEAT OR CHANGE:
- do not return or rewrite preservation_promises, verification_contracts, DNT, prohibitions, owners,
  repository paths, repository evidence, seed IDs, impact IDs, or surface IDs;
- do not return an excluded support/evidence/inherited-only slot;
- do not add a slot, omit a required slot, duplicate a slot, invent a target, or migrate ownership
  unless the full frame explicitly exposes AUTHORITY_CHANGE.

Return only {{"decisions":[{{"slot_id":"...","decision":"...","chosen_target":"...",
"reason_code":"...","bounded_rationale":"..."}}]}}. Do not write code, inspect files, call tools,
or reproduce raw source.

DECISION-RELEVANT IMPACT CHOICE PROJECTION:
{json.dumps(context, ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)}"""


def _record_impact_decision_validation(result):
    """Publish compact V24.3 choice-validation metrics without model work."""
    value = result if isinstance(result, dict) else {}
    RUN["impact_decision_choices_received"] = RUN.get(
        "impact_decision_choices_received", 0,
    ) + int(value.get("received", 0) or 0)
    errors = set(str(item) for item in value.get("errors", []) or [])
    if stage3.DUPLICATE_IMPACT_DECISION_SLOT in errors:
        RUN["impact_decision_duplicate_slots"] = RUN.get(
            "impact_decision_duplicate_slots", 0,
        ) + 1
    if stage3.MISSING_IMPACT_DECISION_SLOT in errors:
        RUN["impact_decision_missing_slots"] = RUN.get(
            "impact_decision_missing_slots", 0,
        ) + 1
    if stage3.UNKNOWN_IMPACT_DECISION_SLOT in errors:
        RUN["impact_decision_unknown_slots"] = RUN.get(
            "impact_decision_unknown_slots", 0,
        ) + 1
    if not value.get("valid"):
        RUN["impact_decision_invalid_choices"] = RUN.get(
            "impact_decision_invalid_choices", 0,
        ) + 1


def _record_impact_frame_coverage(result):
    value = result if isinstance(result, dict) else {}
    RUN["impact_obligations_total"] = max(
        RUN.get("impact_obligations_total", 0), int(value.get("obligations_total", 0) or 0),
    )
    RUN["impact_frame_covered_obligations"] = max(
        RUN.get("impact_frame_covered_obligations", 0),
        int(value.get("covered_obligations", 0) or 0),
    )
    RUN["impact_frame_uncovered_obligations"] = max(
        RUN.get("impact_frame_uncovered_obligations", 0),
        len(value.get("uncovered_obligations", []) or []),
    )
    coverage = value.get("coverage") if isinstance(value.get("coverage"), dict) else {}
    metrics = coverage.get("metrics") if isinstance(coverage.get("metrics"), dict) else {}
    RUN["impact_behavior_change_obligations"] = max(
        RUN.get("impact_behavior_change_obligations", 0),
        int(metrics.get("impact_behavior_change_obligations", 0) or 0),
    )
    if (
        value.get("status") == stage3.IMPACT_FRAME_REQUIREMENT_CAPABILITY_GAP
        or value.get("coverage_status") == stage3.IMPACT_FRAME_REQUIREMENT_CAPABILITY_GAP
    ):
        RUN["impact_frame_capability_gaps"] = RUN.get(
            "impact_frame_capability_gaps", 0,
        ) + 1


def _record_impact_choice_coverage(result):
    value = result if isinstance(result, dict) else {}
    coverage = value.get("coverage") if isinstance(value.get("coverage"), dict) else {}
    metrics = coverage.get("metrics") if isinstance(coverage.get("metrics"), dict) else {}
    RUN["impact_choice_covered_obligations"] = max(
        RUN.get("impact_choice_covered_obligations", 0),
        int(metrics.get("impact_choice_covered_obligations", 0) or 0),
    )
    RUN["impact_choice_uncovered_obligations"] = max(
        RUN.get("impact_choice_uncovered_obligations", 0),
        len(value.get("uncovered_obligations", []) or []),
    )
    RUN["impact_requirements_assigned"] = max(
        RUN.get("impact_requirements_assigned", 0),
        int(metrics.get("impact_requirements_assigned", 0) or 0),
    )
    if str(value.get("status") or "").startswith(stage3.IMPACT_CHOICE_REQUIREMENT_GAP):
        RUN["impact_choice_requirement_gaps"] = RUN.get(
            "impact_choice_requirement_gaps", 0,
        ) + 1


def _create_impact_map_from_decision_frame(
    task_brain, contract, repository_evidence, requirements, registry,
    seeds, planning_packet, structured_call, verified_planning_context,
):
    """Run the V24.4 frame -> choice-coverage -> compiled-map path."""
    core = planning_packet.get("canonical_mandatory_planning_core", {})
    frame = stage3.build_impact_decision_frame(
        task_brain, requirements, repository_evidence,
        surface_registry=registry, impact_seeds=seeds,
        verified_planning_context=verified_planning_context,
        mandatory_core=core,
    )
    RUN["impact_decision_frame"] = copy.deepcopy(frame)
    RUN["impact_decision_frames_created"] = RUN.get(
        "impact_decision_frames_created", 0,
    ) + 1
    RUN["impact_decision_slots_required"] = RUN.get(
        "impact_decision_slots_required", 0,
    ) + len(frame.get("decision_slots", []) or [])
    record_run_event(
        "impact_decision_frame_created", frame_hash=frame.get("frame_hash"),
        slot_count=len(frame.get("decision_slots", []) or []),
        frame_complete=frame.get("frame_complete"), frame_errors=frame.get("frame_errors", []),
        model_calls=0,
    )
    frame_validation = stage3.validate_impact_decision_frame(frame)
    RUN["impact_decision_frame_validation"] = copy.deepcopy(frame_validation)
    RUN["impact_decision_frame_coverage"] = copy.deepcopy(
        frame_validation.get("coverage") or frame.get("impact_decision_frame_coverage", {})
    )
    _record_impact_frame_coverage(frame_validation)
    if not frame_validation.get("valid"):
        RUN["impact_decision_frame_incomplete"] = RUN.get(
            "impact_decision_frame_incomplete", 0,
        ) + 1
        status = frame_validation.get("status") or stage3.IMPACT_DECISION_FRAME_INCOMPLETE
        RUN["orchestration_failure"] = status
        RUN["planning_packet_status"] = status
        record_run_event(
            "impact_decision_frame_incomplete",
            status=status,
            uncovered_obligations=frame_validation.get("uncovered_obligations", []),
            errors=frame_validation.get("errors", []), model_calls=0,
        )
        raise ImpactPlanningError(
            f"{status}: "
            + "; ".join(frame_validation.get("errors", [])),
            status=status,
        )

    decision_packet = stage3.build_impact_decision_packet(
        frame, role="ImpactPlanner", max_chars=stage3.MAX_PLANNER_CONTEXT_CHARS,
        render=_planning_provider_renderer(
            _impact_decision_frame_prompt, stage3.impact_decision_choice_schema(),
        ),
        base_render=_impact_decision_frame_prompt,
        legacy_render=_impact_decision_frame_prompt_v24_4_2,
        mandatory_core=core,
    )
    projection = decision_packet.get("projection") or {}
    projection_metrics = decision_packet.get("projection_metrics", {})
    RUN["impact_choice_projection_builds"] = RUN.get(
        "impact_choice_projection_builds", 0,
    ) + 1
    RUN["impact_frame_slots_total"] = max(
        RUN.get("impact_frame_slots_total", 0),
        int(projection_metrics.get(
            "impact_frame_slots_total", len(frame.get("decision_slots", []) or [])
        ) or 0),
    )
    RUN["impact_model_choice_slots_required"] = max(
        RUN.get("impact_model_choice_slots_required", 0),
        int(projection_metrics.get("impact_model_choice_slots_required", 0) or 0),
    )
    RUN["impact_slots_inherited_only"] = max(
        RUN.get("impact_slots_inherited_only", 0),
        int(projection_metrics.get("impact_slots_inherited_only", 0) or 0),
    )
    RUN["impact_slots_evidence_only"] = max(
        RUN.get("impact_slots_evidence_only", 0),
        int(projection_metrics.get("impact_slots_evidence_only", 0) or 0),
    )
    RUN["impact_choice_projection_chars"] = max(
        RUN.get("impact_choice_projection_chars", 0),
        int(projection_metrics.get("impact_choice_projection_chars", 0) or 0),
    )
    RUN["impact_choice_projection_semantic_coverage"] = min(
        float(RUN.get("impact_choice_projection_semantic_coverage", 1.0) or 0.0),
        float(projection_metrics.get(
            "impact_choice_projection_semantic_coverage", 1.0
        ) or 0.0),
    )
    decision_role_packet = decision_packet.get("role_packet")
    RUN["impact_decision_choice_projection"] = copy.deepcopy(projection)
    RUN["impact_decision_choice_projection_validation"] = copy.deepcopy(
        decision_packet.get("projection_validation", {})
    )
    RUN["impact_decision_legacy_payload_audit"] = copy.deepcopy(
        decision_packet.get("legacy_payload_audit", {})
    )
    RUN["impact_decision_packet"] = copy.deepcopy(decision_packet.get("packet", {}))
    RUN["impact_decision_packet_observability"] = copy.deepcopy(
        decision_role_packet or {}
    )
    _record_planning_role_packet(decision_role_packet)
    RUN["impact_planning_role_packet"] = copy.deepcopy(decision_role_packet)
    RUN["impact_planning_packet"] = copy.deepcopy(decision_packet.get("packet", {}))
    RUN["impact_planning_packet_observability"] = copy.deepcopy(
        decision_packet.get("role_packet", {})
    )
    record_run_event(
        "impact_decision_packet_created",
        frame_hash=frame.get("frame_hash"),
        packet_chars=decision_packet.get("packet_chars"),
        packet_complete=decision_packet.get("packet_complete"),
        packet_hash=(decision_role_packet or {}).get("packet_hash"),
        exact_model_input=(decision_role_packet or {}).get("exact_model_input"),
        projection_hash=decision_packet.get("projection_hash"),
        required_choice_slot_ids=decision_packet.get("required_choice_slot_ids", []),
        excluded_choice_slot_ids=decision_packet.get("excluded_choice_slot_ids", []),
    )
    if not decision_packet.get("packet_complete"):
        RUN["impact_planning_context_incomplete"] = RUN.get(
            "impact_planning_context_incomplete", 0,
        ) + 1
        status = decision_packet.get("status") or stage3.PLANNING_PACKET_PROVIDER_OVERFLOW
        RUN["planning_packet_status"] = status
        RUN["orchestration_failure"] = status
        raise ImpactPlanningError(
            f"{status}: " + "; ".join(decision_packet.get("errors", [])),
            status=status,
        )

    context = decision_packet.get("packet", {})
    RUN.setdefault("control_flow", []).append("IMPACT_PLANNER")
    RUN["impact_planner_calls"] = RUN.get("impact_planner_calls", 0) + 1
    RUN["impact_planner_context"] = copy.deepcopy(context)
    prompt_text = (
        decision_role_packet.get("exact_model_input")
        if isinstance(decision_role_packet, dict)
        else _impact_decision_frame_prompt(context)
    )
    last_validation = {"valid": False, "errors": [stage3.IMPACT_DECISION_OUTPUT_MALFORMED]}

    full_frame_slot_ids = {
        str(item.get("slot_id")) for item in list(frame.get("decision_slots", []) or [])
        if isinstance(item, dict) and item.get("slot_id")
    }

    def projection_for_candidate(data):
        # The injected callback is a compatibility seam used by frozen
        # pre-V24.4.3 callers.  A complete legacy full-slot response retains
        # its old contract; the actual provider path and projected responses
        # use the strict required-slot contract.
        if structured_call is not None and isinstance(data, dict):
            received_ids = {
                str(item.get("slot_id"))
                for item in list(data.get("decisions", []) or [])
                if isinstance(item, dict) and item.get("slot_id")
            }
            if received_ids == full_frame_slot_ids:
                return None
        return projection

    def validator(data):
        nonlocal last_validation
        # The provider callback validates JSON shape, slot cardinality, and
        # frame readiness.  Coverage is deliberately checked once after the
        # provider returns, so a weak but structurally valid choice cannot
        # trigger generic repair/retry behavior.
        last_validation = stage3.validate_impact_decision_choices(
            data, frame, include_coverage=False,
            projection=projection_for_candidate(data),
        )
        _record_impact_decision_validation(last_validation)
        return last_validation

    try:
        if structured_call is None:
            candidate = structured_model_call(
                prompt_text, validator, "impact-decision", stage3.impact_decision_choice_schema(),
                retries=1, role="ImpactPlanner", role_packet=decision_role_packet,
            )
        else:
            candidate = structured_call(
                prompt_text, validator, "impact-decision", stage3.impact_decision_choice_schema(),
            )
    except PlanningPacketBudgetError as exc:
        status = getattr(exc, "code", stage3.PLANNING_PACKET_PROVIDER_OVERFLOW)
        RUN["planning_packet_status"] = status
        RUN["orchestration_failure"] = status
        raise ImpactPlanningError(str(exc), status=status) from exc
    except StructuredOutputError as exc:
        RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
        record_run_event(
            "impact_decision_output_invalid", error=str(exc),
            validation=last_validation,
        )
        raise ImpactPlanningError(
            f"{stage3.IMPACT_DECISION_OUTPUT_MALFORMED}: {exc}",
            status=stage3.IMPACT_DECISION_OUTPUT_MALFORMED,
        ) from exc

    selected_projection = projection_for_candidate(candidate)
    choice_validation = stage3.validate_impact_decision_choices(
        candidate, frame, projection=selected_projection,
    )
    if not last_validation.get("valid") or last_validation.get("choices") != choice_validation.get("choices"):
        # A callback may not have called the supplied validator.  Count this
        # deterministic final gate exactly once for that callback path.
        if last_validation.get("choices") != choice_validation.get("choices"):
            _record_impact_decision_validation(choice_validation)
    RUN["impact_decision_choice_validation"] = copy.deepcopy(choice_validation)
    RUN["impact_decision_choice_coverage"] = copy.deepcopy(
        choice_validation.get("choice_coverage") or {}
    )
    _record_impact_choice_coverage(choice_validation)
    RUN["raw_impact_decision_choices"] = copy.deepcopy(candidate)
    RUN["raw_impact_planner_output"] = copy.deepcopy(candidate)
    record_run_event(
        "impact_decision_choices_captured", choices=candidate,
        validation=choice_validation,
    )
    if not choice_validation.get("valid"):
        RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
        if str(choice_validation.get("status") or "").startswith(
            stage3.IMPACT_CHOICE_REQUIREMENT_GAP
        ):
            RUN["orchestration_failure"] = stage3.IMPACT_CHOICE_REQUIREMENT_GAP
            RUN["planning_packet_status"] = stage3.IMPACT_CHOICE_REQUIREMENT_GAP
            RUN["impact_choice_coverage_failure"] = (
                stage3.DOWNSTREAM_WEAK_IMPACT_CHOICE_COVERAGE_FAILURE
            )
            record_run_event(
                "impact_decision_choice_coverage_incomplete",
                status=stage3.IMPACT_CHOICE_REQUIREMENT_GAP,
                classification=stage3.DOWNSTREAM_WEAK_IMPACT_CHOICE_COVERAGE_FAILURE,
                uncovered_obligations=choice_validation.get("uncovered_obligations", []),
                model_calls=0,
            )
        raise ImpactPlanningError(
            f"{choice_validation.get('status') or stage3.IMPACT_DECISION_OUTPUT_MALFORMED}: "
            + "; ".join(choice_validation.get("errors", [])),
            status=choice_validation.get("status") or stage3.IMPACT_DECISION_OUTPUT_MALFORMED,
        )

    provider_generation_identity = {
        "model": MODEL,
        "provider": "ollama",
        "role": "ImpactPlanner",
        "run_id": RUN_ID,
        "generation": RUN.get("impact_planner_calls", 0),
    }
    compiled = stage3.compile_impact_map_from_choices(
        frame, choice_validation, requirements, repository_evidence,
        surface_registry=registry, impact_seeds=seeds,
        task_goal=_authoritative_stage3_task_goal(contract, task_brain),
        provider_generation_identity=provider_generation_identity,
        projection=selected_projection,
    )
    RUN["impact_decision_compilation"] = copy.deepcopy(compiled)
    if not compiled.get("valid"):
        RUN["impact_map_compile_failures"] = RUN.get(
            "impact_map_compile_failures", 0,
        ) + 1
        RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
        record_run_event(
            "impact_map_compile_invalid", errors=compiled.get("errors", []),
            model_calls=compiled.get("model_calls", 0),
        )
        raise ImpactPlanningError(
            f"{stage3.IMPACT_MAP_COMPILE_INVALID}: "
            + "; ".join(compiled.get("errors", [])),
            status=stage3.IMPACT_MAP_COMPILE_INVALID,
        )
    impact_map = compiled.get("impact_map")
    validation = stage3.validate_impact_map(
        impact_map, requirements, repository_evidence, EXISTING_PROJECT,
        surface_registry=registry,
    )
    RUN["impact_map_hydration"] = compiled.get("hydration")
    RUN["impact_map_validation"] = validation
    if not validation.get("valid"):
        RUN["impact_map_compile_failures"] = RUN.get(
            "impact_map_compile_failures", 0,
        ) + 1
        RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
        raise ImpactPlanningError(
            f"{stage3.IMPACT_MAP_COMPILE_INVALID}: "
            + "; ".join(validation.get("errors", [])),
            status=stage3.IMPACT_MAP_COMPILE_INVALID,
        )
    RUN["impact_maps_compiled_from_choices"] = RUN.get(
        "impact_maps_compiled_from_choices", 0,
    ) + 1
    RUN.setdefault("control_flow", []).append("IMPACT_MAP")
    RUN["impact_map"] = impact_map
    RUN["canonical_impact_map"] = impact_map
    RUN["impact_candidates"] = RUN.get("impact_candidates", 0) + validation.get("impact_candidates", 0)
    RUN["impact_supported"] = RUN.get("impact_supported", 0) + validation.get("impact_supported", 0)
    RUN["impact_preservation_only"] = RUN.get("impact_preservation_only", 0) + validation.get(
        "impact_preservation_only", 0,
    )
    record_run_event(
        "impact_map_created_from_choices", impact_count=len(impact_map.get("impacts", [])),
        serialized_chars=validation.get("serialized_chars"),
        frame_hash=frame.get("frame_hash"), choice_hash=compiled.get("choice_hash"),
        model_calls=compiled.get("model_calls", 0),
    )
    return impact_map


def create_impact_map(task_brain, contract, repository_evidence, structured_call=None,
                      verified_planning_context=None):
    """Invoke one bounded ImpactPlanner call and deterministically gate its map."""
    if RUN.get("impact_planner_calls", 0) >= 1:
        raise ImpactPlanningError("only one top-level ImpactPlanner invocation is allowed")
    requirements = _active_stage3_requirements(contract)
    obligation_ledger = stage3.build_requirement_obligation_ledger(requirements)
    RUN["requirement_obligation_ledger"] = copy.deepcopy(obligation_ledger)
    RUN["requirement_obligations_created"] = obligation_ledger.get("obligation_count", 0)
    RUN["behavior_obligations"] = sum(
        "BEHAVIOR_CHANGE" in item.get("obligation_types", [])
        for item in obligation_ledger.get("requirements", [])
    )
    RUN["impact_obligations_total"] = int(obligation_ledger.get("obligation_count", 0) or 0)
    RUN["impact_behavior_change_obligations"] = sum(
        item.get("obligation_type") == "BEHAVIOR_CHANGE"
        for record in obligation_ledger.get("requirements", [])
        for item in record.get("obligations", []) or []
        if isinstance(item, dict)
    )
    RUN["task_brain"] = copy.deepcopy(task_brain or {})
    registry = stage3.build_canonical_surface_registry(task_brain, repository_evidence)
    registry_validation = stage3.validate_canonical_surface_registry(registry, repository_evidence)
    if not registry_validation.get("valid"):
        raise ImpactPlanningError(
            "IMPACT_MAP_INVALID: canonical surface registry is invalid: "
            + "; ".join(registry_validation.get("errors", []))
        )
    planning_packet = stage3.build_canonical_planning_packet(
        task_brain, requirements, repository_evidence,
        project_invariants=_impact_project_invariants(task_brain),
        surface_registry=registry,
        role="ImpactPlanner",
        render=_planning_provider_renderer(_impact_planner_prompt, stage3.impact_map_schema()),
        base_render=_impact_planner_prompt,
        verified_planning_context=verified_planning_context,
    )
    packet = planning_packet.get("packet", planning_packet)
    packet_observability = planning_packet.get("observability", {})
    RUN["canonical_surface_registry"] = registry
    seeds = copy.deepcopy(planning_packet.get("impact_seeds", []))
    RUN["impact_seeds"] = seeds
    use_decision_frame = isinstance(verified_planning_context, dict)
    if use_decision_frame:
        # V24.2 remains the source of the canonical surface/seed/core audit;
        # the provider-facing packet is replaced below by the smaller choice
        # contract only after the old core has validated successfully.
        RUN["impact_planning_packet_v24_2"] = copy.deepcopy(packet)
        RUN["impact_planning_packet_observability_v24_2"] = copy.deepcopy(packet_observability)
    else:
        RUN["impact_planning_packet"] = copy.deepcopy(packet)
        RUN["impact_planning_packet_observability"] = copy.deepcopy(packet_observability)
    role_packet = planning_packet.get("role_packet")
    if not use_decision_frame:
        _record_planning_role_packet(role_packet)
        RUN["impact_planning_role_packet"] = copy.deepcopy(role_packet)
    for metric, key in (
        ("impact_planning_surfaces_selected", "selected_surface_ids"),
        ("impact_planning_surfaces_serialized", "serialized_surface_ids"),
        ("impact_planning_surfaces_dropped", "dropped_surface_ids"),
    ):
        RUN[metric] = len(packet_observability.get(key, []) or [])
    record_run_event(
        "impact_planning_packet_created", **packet_observability,
        packet_status=planning_packet.get("status"),
    )
    if not planning_packet.get("packet_complete"):
        RUN["impact_planning_context_incomplete"] = RUN.get(
            "impact_planning_context_incomplete", 0,
        ) + 1
        packet_status = planning_packet.get("status") or stage3.IMPACT_PLANNING_CONTEXT_INCOMPLETE
        RUN["planning_packet_status"] = packet_status
        RUN["orchestration_failure"] = stage3.IMPACT_PLANNING_CONTEXT_INCOMPLETE
        record_run_event(
            "impact_planning_context_incomplete",
            errors=planning_packet.get("errors", []),
            packet_observability=packet_observability,
            packet_status=packet_status,
        )
        raise ImpactPlanningError(
            f"{packet_status}: " + "; ".join(planning_packet.get("errors", [])),
            status=packet_status,
        )
    record_run_event(
        "canonical_surface_registry_created", surface_count=len(registry.get("surfaces", [])),
        evidence_count=len(registry.get("evidence_ids", [])), registry=registry,
    )
    packet_validation = stage3.validate_planning_packet(
        planning_packet, registry=registry, requirements=requirements, impact_seeds=seeds,
    )
    if not packet_validation.get("valid"):
        RUN["impact_planning_context_incomplete"] = RUN.get(
            "impact_planning_context_incomplete", 0,
        ) + 1
        RUN["orchestration_failure"] = stage3.IMPACT_PLANNING_CONTEXT_INCOMPLETE
        raise ImpactPlanningError(
            f"{stage3.IMPACT_PLANNING_CONTEXT_INCOMPLETE}: "
            + "; ".join(packet_validation.get("errors", []))
        )
    if use_decision_frame:
        return _create_impact_map_from_decision_frame(
            task_brain, contract, repository_evidence, requirements, registry,
            seeds, planning_packet, structured_call, verified_planning_context,
        )
    context = packet
    RUN.setdefault("control_flow", []).append("IMPACT_PLANNER")
    RUN["impact_planner_calls"] = RUN.get("impact_planner_calls", 0) + 1
    RUN["impact_planner_context"] = context
    prompt_text = role_packet.get("base_rendered_packet") if isinstance(role_packet, dict) else _impact_planner_prompt(context)

    def validator(data):
        return stage3.validate_planner_output(
            data, requirements, allow_legacy=structured_call is not None,
            impact_seeds=seeds,
        )

    try:
        if structured_call is None:
            candidate = structured_model_call(
                prompt_text, validator, "impact-map", stage3.impact_map_schema(),
                retries=1, role="ImpactPlanner", role_packet=role_packet,
            )
        else:
            candidate = structured_call(
                prompt_text, validator, "impact-map", stage3.impact_map_schema(),
            )
        raw_artifact = stage3.normalize_impact_map(candidate)
        RUN["raw_impact_planner_output"] = copy.deepcopy(raw_artifact)
        RUN["raw_impact_map"] = copy.deepcopy(raw_artifact)
        record_run_event("impact_planner_output_captured", raw_impact_map=raw_artifact)
        impact_map = stage3.hydrate_impact_map(
            candidate, registry, requirements, repository_evidence,
            allow_legacy_exact=structured_call is not None,
            impact_seeds=seeds,
        )
        RUN["impact_map_hydration"] = impact_map
        for metric in (
            "impact_unknown_surface_references", "impact_surface_evidence_mismatches",
            "impact_invented_existing_paths_rejected", "impact_invented_interfaces_rejected",
            "impact_unknown_impact_seed_references", "impact_invalid_optional_fields_rejected",
            "impact_invalid_requirement_references_rejected", "impact_seed_surface_binding_conflicts",
        ):
            RUN[metric] = RUN.get(metric, 0) + int(impact_map.get(metric, 0) or 0)
        for metric, fallback in (
            ("impact_seed_decisions_received", "impact_decisions_received"),
            ("impact_seed_decisions_validated", "impact_decisions_validated"),
            ("impact_seed_decisions_rejected", "impact_decisions_rejected"),
        ):
            RUN[metric] = RUN.get(metric, 0) + int(impact_map.get(metric, impact_map.get(fallback, 0)) or 0)
        if not impact_map.get("hydration_valid") or not impact_map.get("impacts"):
            RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
            raise ImpactPlanningError(
                "IMPACT_MAP_INVALID: " + "; ".join(impact_map.get("hydration_errors", []))
            )
        validation = stage3.validate_impact_map(
            impact_map, requirements, repository_evidence, EXISTING_PROJECT,
            surface_registry=registry,
        )
        if not validation.get("valid"):
            RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
            raise ImpactPlanningError(
                "IMPACT_MAP_INVALID: " + "; ".join(validation.get("errors", []))
            )
    except PlanningPacketBudgetError as exc:
        status = getattr(exc, "code", stage3.PLANNING_PACKET_PROVIDER_OVERFLOW)
        RUN["planning_packet_status"] = status
        RUN["orchestration_failure"] = status
        raise ImpactPlanningError(str(exc), status=status) from exc
    except StructuredOutputError as exc:
        RUN["impact_map_failures"] = RUN.get("impact_map_failures", 0) + 1
        record_run_event("impact_planner_invalid", error=str(exc))
        raise ImpactPlanningError("IMPACT_MAP_INVALID: " + str(exc)) from exc
    if not validation.get("valid"):
        raise ImpactPlanningError("IMPACT_MAP_INCOMPLETE: " + "; ".join(validation.get("errors", [])))
    RUN.setdefault("control_flow", []).append("IMPACT_MAP")
    RUN["impact_map"] = impact_map
    RUN["canonical_impact_map"] = impact_map
    RUN["impact_map_validation"] = validation
    RUN["impact_maps_created"] = RUN.get("impact_maps_created", 0) + 1
    RUN["impact_candidates"] = RUN.get("impact_candidates", 0) + validation.get("impact_candidates", 0)
    RUN["impact_supported"] = RUN.get("impact_supported", 0) + validation.get("impact_supported", 0)
    RUN["impact_preservation_only"] = RUN.get("impact_preservation_only", 0) + validation.get(
        "impact_preservation_only", 0,
    )
    record_run_event(
        "impact_map_created", impact_count=len(impact_map.get("impacts", [])),
        serialized_chars=validation.get("serialized_chars"), impact_map=impact_map,
    )
    return impact_map


def _impact_challenger_output_valid(data):
    if not isinstance(data, dict) or not isinstance(data.get("challenges"), list):
        return False
    if len(data.get("challenges", [])) > MAX_IMPACT_CHALLENGES:
        return False
    return all(
        isinstance(item, dict)
        and str(item.get("challenge_type", "")).upper() in stage3.CHALLENGE_TYPES
        and isinstance(item.get("impact_ids"), list)
        and isinstance(item.get("requirement_ids"), list)
        and isinstance(item.get("repository_evidence_ids"), list)
        for item in data.get("challenges", [])
    )


def _impact_challenger_prompt(context):
    return f"""You are IMPACT CHALLENGER, a narrow read-only adversarial planning role.
Try to falsify the candidate Impact Map using only the bounded requirements, accepted repository facts,
ownership, interfaces, tests, and preservation constraints below. Ask whether each MUST_CHANGE surface is
actually necessary, whether ownership is duplicated or wrong, whether a verified interface was missed,
whether a required surface/test/dependency is absent, and whether unrelated scope was introduced.
Use only canonical impact/surface IDs from the supplied map and registry; do not invent paths, symbols,
owners, interfaces, or evidence. Every challenge must cite its impact IDs (except a true missing-impact gap),
Source Requirement IDs, and applicable REPO evidence IDs. Unsupported criticism is not authoritative.
Deterministically evaluate unsupported necessity, wrong owner, duplicate ownership, missing impact, unrelated
change, preservation risk, missed interface reuse, test/dependency/requirement gaps. Do not review code, write
code, call tools, inspect the full repository, or claim perfect correctness. Return only structured challenges.

COMPLETE BOUNDED FALSIFICATION PACKET:
{json.dumps(context, ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)}"""


def challenge_impact_map(impact_map, task_brain, contract, repository_evidence,
                         structured_call=None, verified_planning_context=None):
    """Run exactly one normal weak-model challenge round plus deterministic checks."""
    if RUN.get("impact_challenger_calls", 0) >= MAX_IMPACT_CHALLENGE_ROUNDS:
        raise ImpactPlanningError("only one top-level ImpactChallenger round is allowed")
    requirements = _active_stage3_requirements(contract)
    registry = RUN.get("canonical_surface_registry") or stage3.build_canonical_surface_registry(
        task_brain, repository_evidence,
    )
    challenger_packet = stage3.build_challenger_packet(
        impact_map, requirements, repository_evidence, task_brain,
        surface_registry=registry, role="ImpactChallenger",
        render=_planning_provider_renderer(_impact_challenger_prompt, stage3.challenge_schema()),
        base_render=_impact_challenger_prompt,
        verified_planning_context=verified_planning_context,
    )
    context = challenger_packet.get("packet", challenger_packet)
    packet_observability = challenger_packet.get("observability", {})
    review_projection = challenger_packet.get("challenger_review_projection")
    if isinstance(review_projection, dict):
        projection_metrics = review_projection.get("metrics", {})
        RUN["challenger_review_projection_builds"] = RUN.get(
            "challenger_review_projection_builds", 0,
        ) + 1
        for metric_name in (
            "challenger_impacts_total", "challenger_primary_impacts",
            "challenger_fixed_context_units", "challenger_evidence_support_units",
            "challenger_projection_chars",
        ):
            RUN[metric_name] = projection_metrics.get(metric_name, RUN.get(metric_name, 0))
        RUN["challenger_review_semantic_coverage"] = projection_metrics.get(
            "challenger_review_semantic_coverage",
            RUN.get("challenger_review_semantic_coverage", 1.0),
        )
        RUN["impact_challenger_review_projection"] = copy.deepcopy(review_projection)
        record_run_event(
            "challenger_review_projection_built",
            projection_hash=review_projection.get("projection_hash"),
            projection_metrics=copy.deepcopy(projection_metrics),
            full_map_authority_coverage=review_projection.get("full_map_authority_coverage"),
            full_provenance_reachable=review_projection.get("full_provenance_reachable"),
        )
    role_packet = challenger_packet.get("role_packet")
    _record_planning_role_packet(role_packet)
    RUN["impact_challenger_role_packet"] = copy.deepcopy(role_packet)
    RUN["impact_challenger_packet_observability"] = copy.deepcopy(packet_observability)
    if not challenger_packet.get("packet_complete", context.get("packet_complete", True)):
        RUN["impact_challenger_context_incomplete"] = RUN.get(
            "impact_challenger_context_incomplete", 0,
        ) + 1
        packet_status = challenger_packet.get("status") or stage3.IMPACT_CHALLENGER_CONTEXT_INCOMPLETE
        RUN["planning_packet_status"] = packet_status
        RUN["orchestration_failure"] = stage3.IMPACT_CHALLENGER_CONTEXT_INCOMPLETE
        record_run_event(
            "impact_challenger_context_incomplete",
            errors=challenger_packet.get("errors", []),
            packet_observability=packet_observability,
            packet_status=packet_status,
        )
        raise ImpactPlanningError(
            f"{packet_status}: " + "; ".join(challenger_packet.get("errors", [])),
            status=packet_status,
        )
    RUN.setdefault("control_flow", []).append("IMPACT_CHALLENGER")
    RUN["impact_challenger_calls"] = RUN.get("impact_challenger_calls", 0) + 1
    RUN["impact_challenger_context"] = context
    prompt_text = (
        role_packet.get("base_rendered_packet")
        if isinstance(role_packet, dict) else _impact_challenger_prompt(context)
    )
    try:
        if structured_call is None:
            data = structured_model_call(
                prompt_text, _impact_challenger_output_valid, "impact-challenge",
                stage3.challenge_schema(), retries=1, role="ImpactChallenger",
                role_packet=role_packet,
            )
        else:
            data = structured_call(
                prompt_text, _impact_challenger_output_valid, "impact-challenge",
                stage3.challenge_schema(),
            )
        model_challenges = stage3.normalize_challenges(data, source="MODEL")
        RUN["raw_impact_challenger_output"] = copy.deepcopy(model_challenges)
        record_run_event("impact_challenger_output_captured", raw_challenges=model_challenges)
    except PlanningPacketBudgetError as exc:
        status = getattr(exc, "code", stage3.PLANNING_PACKET_PROVIDER_OVERFLOW)
        RUN["planning_packet_status"] = status
        RUN["orchestration_failure"] = status
        raise ImpactPlanningError(str(exc), status=status) from exc
    except StructuredOutputError as exc:
        model_challenges = []
        RUN["raw_impact_challenger_output"] = []
        record_run_event("impact_challenger_structured_fallback", error=str(exc))
    deterministic = stage3.deterministic_challenges(
        impact_map, requirements, repository_evidence, surface_registry=registry,
    )
    challenges = stage3.merge_challenges(model_challenges, deterministic)
    validation = stage3.validate_challenges(
        challenges, impact_map, requirements, repository_evidence,
        surface_registry=registry,
    )
    RUN["impact_challenges"] = RUN.get("impact_challenges", 0) + len(challenges)
    RUN["impact_challenges_validated"] = RUN.get("impact_challenges_validated", 0) + len(
        validation.get("validated", []),
    )
    RUN["impact_challenges_rejected"] = RUN.get("impact_challenges_rejected", 0) + len(
        validation.get("rejected", []),
    )
    RUN["impact_challenges_applicable"] = RUN.get("impact_challenges_applicable", 0) + len(
        validation.get("applicable", []),
    )
    RUN["impact_challenges_non_applicable"] = RUN.get("impact_challenges_non_applicable", 0) + len(
        validation.get("non_applicable", []),
    )
    RUN["impact_challenge_rounds"] = 1
    RUN["impact_challenges_output"] = challenges
    RUN["impact_challenge_validation"] = validation
    RUN["validated_impact_challenges"] = validation.get("validated", [])
    RUN["rejected_impact_challenges"] = validation.get("rejected", [])
    record_run_event(
        "impact_challenges_validated", challenge_count=len(challenges),
        validated_count=len(validation.get("validated", [])),
        rejected_count=len(validation.get("rejected", [])),
    )
    return validation


def _bounded_impact_revision_context(context):
    """Bound revision metadata without truncating the canonical packet."""
    value = copy.deepcopy(context) if isinstance(context, dict) else {}
    candidate = value.get("candidate_impact_map")
    if isinstance(candidate, dict):
        impact_keys = (
            "impact_id", "surface_id", "canonical_surface_id", "disposition",
            "impact_kind", "necessity_status", "requirement_ids",
            "repository_evidence_ids", "action", "interfaces_to_reuse",
            "existing_interfaces_to_reuse", "preserve", "verification",
            "surface_kind", "surface_role", "owner_surface_id",
        )
        candidate["impacts"] = [
            {
                key: copy.deepcopy(impact.get(key))
                for key in impact_keys
                if impact.get(key) not in (None, "", [], {})
            }
            for impact in list(candidate.get("impacts", []) or [])
            if isinstance(impact, dict)
        ]
        for impact in list(candidate.get("impacts", []) or []):
            if not isinstance(impact, dict):
                continue
            for field in ("action", "reason", "candidate_change"):
                if isinstance(impact.get(field), str):
                    impact[field] = compact_text(impact[field], 360)
    challenges = value.get("validated_challenges")
    if isinstance(challenges, list):
        challenge_keys = (
            "challenge_id", "challenge_type", "impact_ids", "surface_ids",
            "requirement_ids", "repository_evidence_ids",
            "proposed_resolution", "blocking",
        )
        value["validated_challenges"] = [{
            key: compact_text(challenge.get(key), 220)
            if key in {"claim", "proposed_resolution"} else copy.deepcopy(challenge.get(key))
            for key in challenge_keys if challenge.get(key) not in (None, "", [], {})
        } for challenge in challenges if isinstance(challenge, dict)]
    if isinstance(value.get("user_confirmed_revision"), dict):
        value["user_confirmed_revision"] = {
            key: compact_text(item, 320) if isinstance(item, str) else copy.deepcopy(item)
            for key, item in value["user_confirmed_revision"].items()
        }
    encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    return value, len(encoded) <= stage3.MAX_REVISION_CONTEXT_CHARS


def _impact_revision_prompt(context):
    bounded_context, _ = _bounded_impact_revision_context(context)
    return f"""You are IMPACT PLAN REVISER. Perform the single allowed bounded revision of an existing-project
Impact Map. Use only the current candidate map, validated challenges, explicit USER_CONFIRMED revision (if
present), Source Requirements, and accepted repository facts below. Resolve supported criticism without
inventing surfaces, preserve verified ownership, reuse verified interfaces, retain preservation-only surfaces,
and keep explicit test responsibility. Every concrete impact still requires valid requirement and REPO evidence
IDs. Do not write code, call tools, inspect raw files, or debate. Return only one complete Impact Map.

COMPLETE BOUNDED REVISION CONTEXT:
{json.dumps(bounded_context, ensure_ascii=False, sort_keys=True, separators=(',', ':'), default=str)}"""


def revise_impact_map(impact_map, validated_challenges, task_brain, contract,
                      repository_evidence, user_revision=None, structured_call=None,
                      verified_planning_context=None):
    if RUN.get("impact_plan_revision_calls", 0) >= MAX_IMPACT_PLAN_REVISION_ROUNDS:
        raise ImpactPlanningError("the bounded Impact Plan revision round is already exhausted")
    requirements = _active_stage3_requirements(contract)
    registry = RUN.get("canonical_surface_registry") or stage3.build_canonical_surface_registry(
        task_brain, repository_evidence,
    )
    planning_packet = stage3.build_canonical_planning_packet(
        task_brain, requirements, repository_evidence,
        project_invariants=_impact_project_invariants(task_brain),
        surface_registry=registry,
        verified_planning_context=verified_planning_context,
    )
    planner_context = planning_packet.get("packet", planning_packet)
    if not planning_packet.get("packet_complete"):
        packet_status = planning_packet.get("status") or stage3.IMPACT_PLAN_REVISION_CONTEXT_INCOMPLETE
        RUN["planning_packet_status"] = packet_status
        RUN["orchestration_failure"] = packet_status
        raise ImpactPlanningError(
            f"{packet_status}: " + "; ".join(planning_packet.get("errors", [])),
            status=packet_status,
        )
    context = {
        "candidate_impact_map": impact_map,
        "validated_challenges": list(validated_challenges or [])[:MAX_IMPACT_CHALLENGES],
        "user_confirmed_revision": _compact_brain_record(user_revision, 900)
        if isinstance(user_revision, dict) else None,
        "planning_packet": planner_context,
    }
    context, _ = _bounded_impact_revision_context(context)
    revision_packet = stage3.build_revision_packet(
        context, max_chars=stage3.MAX_REVISION_CONTEXT_CHARS,
        role="ImpactPlanReviser",
        render=_planning_provider_renderer(_impact_revision_prompt, stage3.impact_map_schema()),
        base_render=_impact_revision_prompt,
        source_planning_context_hash=(
            verified_planning_context or {}
        ).get("planning_context_hash") if isinstance(verified_planning_context, dict) else None,
    )
    role_packet = revision_packet.get("role_packet")
    _record_planning_role_packet(role_packet)
    RUN["impact_plan_revision_role_packet"] = copy.deepcopy(role_packet)
    RUN["impact_plan_revision_packet_observability"] = copy.deepcopy(
        revision_packet.get("observability", {})
    )
    if not revision_packet.get("packet_complete"):
        RUN["impact_planning_context_incomplete"] = RUN.get(
            "impact_planning_context_incomplete", 0,
        ) + 1
        RUN["orchestration_failure"] = revision_packet.get(
            "status", stage3.IMPACT_PLAN_REVISION_CONTEXT_INCOMPLETE,
        )
        record_run_event(
            "impact_plan_revision_context_incomplete",
            status=revision_packet.get("status"),
            errors=revision_packet.get("errors", []),
            packet_observability=revision_packet.get("observability", {}),
        )
        RUN["planning_packet_status"] = revision_packet.get(
            "status", stage3.IMPACT_PLAN_REVISION_CONTEXT_INCOMPLETE,
        )
        raise ImpactPlanningError(
            f"{revision_packet.get('status', stage3.IMPACT_PLAN_REVISION_CONTEXT_INCOMPLETE)}: "
            + "; ".join(revision_packet.get("errors", [])),
            status=revision_packet.get("status", stage3.IMPACT_PLAN_REVISION_CONTEXT_INCOMPLETE),
        )
    context = revision_packet.get("packet", context)
    RUN["impact_plan_revision_calls"] = RUN.get("impact_plan_revision_calls", 0) + 1
    prompt_text = (
        role_packet.get("base_rendered_packet")
        if isinstance(role_packet, dict) else _impact_revision_prompt(context)
    )

    def validator(data):
        return stage3.validate_planner_output(
            data, requirements, allow_legacy=structured_call is not None,
            impact_seeds=RUN.get("impact_seeds", []),
        )

    try:
        if structured_call is None:
            data = structured_model_call(
                prompt_text, validator, "impact-plan-revision", stage3.impact_map_schema(),
                retries=1, role="ImpactPlanReviser", role_packet=role_packet,
            )
        else:
            data = structured_call(
                prompt_text, validator, "impact-plan-revision", stage3.impact_map_schema(),
            )
        revised = stage3.hydrate_impact_map(
            data, registry, requirements, repository_evidence,
            allow_legacy_exact=structured_call is not None,
            impact_seeds=RUN.get("impact_seeds", []),
        )
        for metric in (
            "impact_unknown_surface_references", "impact_surface_evidence_mismatches",
            "impact_invented_existing_paths_rejected", "impact_invented_interfaces_rejected",
            "impact_unknown_impact_seed_references", "impact_invalid_optional_fields_rejected",
            "impact_invalid_requirement_references_rejected", "impact_seed_surface_binding_conflicts",
        ):
            RUN[metric] = RUN.get(metric, 0) + int(revised.get(metric, 0) or 0)
        for metric, fallback in (
            ("impact_seed_decisions_received", "impact_decisions_received"),
            ("impact_seed_decisions_validated", "impact_decisions_validated"),
            ("impact_seed_decisions_rejected", "impact_decisions_rejected"),
        ):
            RUN[metric] = RUN.get(metric, 0) + int(revised.get(metric, revised.get(fallback, 0)) or 0)
        if not revised.get("hydration_valid"):
            raise StructuredOutputError("; ".join(revised.get("hydration_errors", [])))
        validation = stage3.validate_impact_map(
            revised, requirements, repository_evidence, EXISTING_PROJECT,
            surface_registry=registry,
        )
        if not validation.get("valid"):
            raise StructuredOutputError("; ".join(validation.get("errors", [])))
    except StructuredOutputError as exc:
        record_run_event("impact_plan_revision_fallback", error=str(exc))
        revised = stage3.deterministic_impact_map(
            (task_brain or {}).get("task_goal", {}).get("text", "coding task"),
            requirements, repository_evidence, registry=registry,
        )
    return revised


def reconcile_minimal_change_plan(impact_map, challenge_validation, contract,
                                  repository_evidence, verified_planning_context=None):
    requirements = _active_stage3_requirements(contract)
    obligation_aware = isinstance(verified_planning_context, dict)
    task_brain = RUN.get("task_brain") or {}
    registry = RUN.get("canonical_surface_registry") or stage3.build_canonical_surface_registry(
        task_brain, repository_evidence,
    )
    RUN.setdefault("control_flow", []).append("PLAN_RECONCILIATION")
    obligation_ledger = stage3.build_requirement_obligation_ledger(requirements)
    RUN["requirement_obligation_ledger"] = copy.deepcopy(obligation_ledger)
    authoritative_task_goal = _authoritative_stage3_task_goal(contract, task_brain)
    reconciled, resolved, unresolved = stage3.reconcile_impact_map(
        impact_map, challenge_validation.get("validated", []),
        requirements, repository_evidence, surface_registry=registry,
        impact_seeds=RUN.get("impact_seeds", []),
        obligation_ledger=obligation_ledger,
        task_goal=authoritative_task_goal,
        task_brain=task_brain,
        obligation_aware=obligation_aware,
    )
    RUN.setdefault("control_flow", []).append("MINIMAL_EFFECTIVE_CHANGE_PLAN")
    plan = stage3.build_minimal_change_plan(
        reconciled, requirements, repository_evidence,
        resolved_challenges=resolved, unresolved_challenges=unresolved,
        project_mode=EXISTING_PROJECT,
        surface_registry=registry,
        obligation_ledger=obligation_ledger,
        task_goal=authoritative_task_goal,
        obligation_aware=obligation_aware,
    )
    # Recompute challenge lifecycle against the actual final plan payload.
    # The impact map is retained as the canonical target lookup so omitted
    # preservation/interface surfaces remain auditable even when they are
    # represented in plan-level sections rather than mutation nodes.
    final_lifecycle, resolved, unresolved = stage3.re_evaluate_challenge_lifecycle(
        challenge_validation.get("validated", []), plan, requirements,
        repository_evidence, surface_registry=registry,
        obligation_ledger=obligation_ledger, impact_map=reconciled,
        closure_actions=reconciled.get("behavior_anchor_closure_actions", []),
    )
    plan["resolved_challenges"] = [
        stage3.compact_challenge_record(item) for item in resolved[:stage3.MAX_CHALLENGES]
    ]
    plan["unresolved_challenges"] = [
        stage3.compact_challenge_record(item) for item in unresolved[:stage3.MAX_CHALLENGES]
    ]
    if isinstance(verified_planning_context, dict):
        # Bind the plan to the exact deterministic V24 context before Stage 3
        # computes plan identity. The full context remains outside the plan;
        # only source hashes and bounded provenance are carried forward.
        plan = stage6b.attach_plan_binding(plan, verified_planning_context)
        chars_before_canonicalization = stage3._json_size(plan)
        nodes_before_canonicalization = len(plan.get("approved_change_nodes", []) or [])
        # V24.4.5 uses a canonical approval-plan representation only after
        # the verified-state binding is present. Legacy Stage 3 callers keep
        # the expanded compatibility representation and its old semantics.
        plan = stage3.canonicalize_final_plan(
            plan,
            impact_map=reconciled,
            requirements=requirements,
            evidence=repository_evidence,
            surface_registry=registry,
            source_impact_map=impact_map,
        )
        # Keep the existing bounded compatibility trimmer as a final
        # deterministic safety pass. It removes only redundant aliases; it
        # never slices or repairs the canonical authority representation.
        plan = stage3._fit_plan_to_serialized_bound(plan)
        RUN["final_plan_canonicalization_metrics"] = {
            "final_plan_chars_before_canonicalization": chars_before_canonicalization,
            "final_plan_chars_after_canonicalization": stage3._json_size(plan),
            "final_plan_semantic_units": sum(
                len(item.get("obligation_ids", []) or [])
                for item in plan.get("approved_change_nodes", []) or []
                if isinstance(item, dict)
            ),
            "final_plan_deduplicated_units": max(
                0,
                nodes_before_canonicalization
                - len(plan.get("approved_change_nodes", []) or []),
            ),
            "final_plan_shared_constraints": sum(
                len(item) for item in (plan.get("canonical_constraints") or {}).values()
                if isinstance(item, list)
            ),
            "final_plan_shared_verification_contracts": len(
                plan.get("canonical_verification_contracts", []) or []
            ),
            "final_plan_provenance_refs": len(plan.get("impact_references", []) or []),
        }
    plan = stage3.finalize_plan_identity(plan)
    reconciled["challenge_lifecycle"] = final_lifecycle
    reconciled["challenges_resolved_post_reconciliation"] = len(resolved)
    reconciled["challenges_remaining_open"] = len(unresolved)
    RUN.setdefault("control_flow", []).append("PLAN_GATE")
    gate = stage3.validate_change_plan(
        plan, requirements, repository_evidence, EXISTING_PROJECT,
        surface_registry=registry,
        obligation_ledger=obligation_ledger,
        authoritative_task_goal=authoritative_task_goal,
        obligation_aware=obligation_aware,
    )
    if isinstance(verified_planning_context, dict):
        v24_gate = stage6b.validate_verified_plan(
            plan,
            verified_planning_context,
            requirements=requirements,
            current_repository_evidence=repository_evidence,
        )
        gate["verified_planning_context_validation"] = v24_gate
        if not v24_gate.get("valid"):
            gate["valid"] = False
            gate.setdefault("errors", []).extend(v24_gate.get("errors", []))
        RUN["verified_planning_context_validation"] = copy.deepcopy(v24_gate)
        RUN["planning_authority_change_blocks"] = RUN.get(
            "planning_authority_change_blocks", 0,
        ) + int(v24_gate.get("authority_change_blocks", 0) or 0)
        RUN["planning_stale_evidence_blocks"] = RUN.get(
            "planning_stale_evidence_blocks", 0,
        ) + int(v24_gate.get("stale_evidence_blocks", 0) or 0)
        RUN["planning_mandatory_authority_drops"] = RUN.get(
            "planning_mandatory_authority_drops", 0,
        ) + int(v24_gate.get("mandatory_authority_drops", 0) or 0)
    RUN["change_plans_created"] = RUN.get("change_plans_created", 0) + 1
    RUN["plan_nodes"] = RUN.get("plan_nodes", 0) + gate.get("plan_nodes", 0)
    RUN["plan_requirements_covered"] = RUN.get("plan_requirements_covered", 0) + gate.get(
        "requirements_covered", 0,
    )
    RUN["plan_requirements_unassigned"] = RUN.get("plan_requirements_unassigned", 0) + gate.get(
        "requirements_unassigned", 0,
    )
    for metric in (
        "behavior_obligations", "behavior_obligations_covered", "behavior_obligations_uncovered",
    ):
        RUN[metric] = int(gate.get(metric, RUN.get(metric, 0)) or 0)
    RUN["requirement_obligations_created"] = int(
        gate.get("requirement_obligations_created", obligation_ledger.get("obligation_count", 0)) or 0
    )
    RUN["deterministic_behavior_anchor_promotions"] = int(
        reconciled.get("deterministic_behavior_anchor_promotions", 0) or 0
    )
    for metric in (
        "impact_challenges_applicable", "impact_challenges_non_applicable",
        "challenge_effects_applied", "challenge_effects_suppressed",
        "obligation_impacts_synthesized", "preservation_obligations_closed",
        "reuse_obligations_closed", "test_obligations_closed",
        "prohibition_obligations_closed",
    ):
        RUN[metric] = int(reconciled.get(metric, RUN.get(metric, 0)) or 0)
    RUN["challenges_resolved_post_reconciliation"] = int(
        reconciled.get("challenges_resolved_post_reconciliation", len(resolved)) or 0
    )
    RUN["challenges_remaining_open"] = int(
        reconciled.get("challenges_remaining_open", len(unresolved)) or 0
    )
    if not gate.get("valid"):
        RUN["change_plan_gate_failures"] = RUN.get("change_plan_gate_failures", 0) + 1
    RUN["reconciled_impact_map"] = reconciled
    RUN["resolved_impact_challenges"] = resolved
    RUN["unresolved_impact_challenges"] = unresolved
    RUN["minimal_effective_change_plan"] = plan
    RUN["change_plan_gate"] = gate
    RUN["plan_gate"] = gate
    record_run_event(
        "minimal_effective_change_plan", plan_id=plan.get("plan_id"),
        plan_hash=plan.get("plan_hash"), gate=gate, plan=plan,
    )
    return plan, gate


def plan_approval_option_labels(allow_revision=True):
    labels = ["Approve plan                         Recommended"]
    if allow_revision:
        labels.append("Review/change scope")
    labels.append("Cancel")
    if allow_revision:
        labels.append("Other...")
    return labels


def navigate_plan_approval_options(key_sequence, initial_index=0, allow_revision=True):
    return navigate_clarification_options(
        plan_approval_option_labels(allow_revision), key_sequence, initial_index,
    )


def format_plan_approval_summary(plan):
    summary = stage3.plan_summary(plan)
    lines = ["\nHIVO reviewed the existing project.\n", "Proposed change plan:"]
    for index, item in enumerate(summary.get("changes", []), 1):
        component = item.get("component") or "Project responsibility"
        mode = "change" if item.get("mutation_required") else "reuse/verify"
        lines.append(f"{index}. {component} [{mode}]\n   {item.get('behavior', '')}")
    if summary.get("preserve"):
        lines.append("\nPreserve:")
        lines.extend(f"- {item}" for item in summary["preserve"])
    if summary.get("tests"):
        lines.append("\nTests:")
        lines.extend(f"- {item}" for item in summary["tests"])
    if summary.get("do_not_touch"):
        lines.append("\nNo change planned:")
        lines.extend(f"- {item}" for item in summary["do_not_touch"])
    return "\n".join(lines)


def select_plan_approval_option(plan, key_sequence=None, output_fn=print,
                                terminal_available=None, allow_revision=True):
    labels = plan_approval_option_labels(allow_revision)
    if key_sequence is not None:
        return navigate_plan_approval_options(key_sequence, allow_revision=allow_revision)
    if terminal_available is None:
        terminal_available = bool(sys.stdin.isatty() and sys.stdout.isatty())
    if not terminal_available:
        return None
    output_fn(format_plan_approval_summary(plan))
    if PROMPT_TOOLKIT_AVAILABLE:
        try:
            from prompt_toolkit.shortcuts import radiolist_dialog
            selected = radiolist_dialog(
                title="HIVO change plan", text="Use Up/Down and Enter to select.",
                values=[(index, label) for index, label in enumerate(labels)],
                ok_text="Select", cancel_text="Cancel",
            ).run()
            return int(selected) if selected is not None else None
        except (ImportError, EOFError, KeyboardInterrupt, TypeError, ValueError):
            return None
    if os.name == "nt":
        try:
            import msvcrt
            index = 0
            while True:
                key = msvcrt.getwch()
                if key in {"\r", "\n"}:
                    return index
                if key == "\x1b":
                    return None
                if key in {"\x00", "\xe0"}:
                    arrow = msvcrt.getwch()
                    if arrow == "H":
                        index = max(0, index - 1)
                    elif arrow == "P":
                        index = min(len(labels) - 1, index + 1)
        except (ImportError, EOFError, KeyboardInterrupt):
            return None
    output_fn("Use arrow keys and Enter; Esc cancels.")
    return None


def _plan_approval_record(plan, status, source, user_revision=None):
    return {
        "plan_id": plan.get("plan_id"),
        "plan_hash": plan.get("plan_hash"),
        "approval_status": status,
        "approved_at": datetime.now().isoformat(timespec="seconds") if status == "APPROVED" else None,
        "approval_source": source,
        "user_revision": copy.deepcopy(user_revision) if isinstance(user_revision, dict) else None,
    }


def request_plan_approval(plan, interactive=True, terminal_available=None, selector=None,
                          answer_reader=None, allow_revision=True):
    RUN.setdefault("control_flow", []).append("USER_PLAN_APPROVAL")
    RUN["plan_approval_requests"] = RUN.get("plan_approval_requests", 0) + 1
    RUN["plan_approval_required"] = RUN.get("plan_approval_required", 0) + 1
    if terminal_available is None:
        terminal_available = bool(sys.stdin.isatty() and sys.stdout.isatty())
    payload = {
        "terminal_state": PLAN_APPROVAL_REQUIRED,
        "plan_id": plan.get("plan_id"), "plan_hash": plan.get("plan_hash"),
        "summary": stage3.plan_summary(plan), "plan": plan,
    }
    RUN["plan_approval_payload"] = payload
    if not interactive or not terminal_available:
        record = _plan_approval_record(plan, "REQUIRED", "NON_INTERACTIVE")
        RUN["plan_approval"] = record
        record_run_event("plan_approval_required", **{
            key: value for key, value in payload.items() if key != "plan"
        })
        return {
            "status": "plan_approval_required", "terminal_state": PLAN_APPROVAL_REQUIRED,
            "summary": "A valid existing-project change plan requires user approval before mutation.",
            "plan": plan, "plan_summary": payload["summary"],
            "approval_payload": payload, "approval": record,
        }
    choose = selector or select_plan_approval_option
    try:
        selected = choose(
            plan, terminal_available=terminal_available, allow_revision=allow_revision,
        )
    except TypeError:
        try:
            selected = choose(plan, terminal_available=terminal_available)
        except TypeError:
            selected = choose(plan)
    labels = plan_approval_option_labels(allow_revision)
    if selected is None:
        selected_label = "Cancel"
    else:
        selected = min(max(int(selected), 0), len(labels) - 1)
        selected_label = labels[selected]
    if selected_label.startswith("Approve plan"):
        record = _plan_approval_record(plan, "APPROVED", "TERMINAL_ARROW_SELECTION")
        RUN["plan_approval"] = record
        RUN["plan_approval_granted"] = RUN.get("plan_approval_granted", 0) + 1
        record_run_event(
            "plan_approved", plan_id=plan.get("plan_id"), plan_hash=plan.get("plan_hash"),
        )
        return {"status": "approved", "plan": plan, "approval": record}
    if allow_revision and selected_label in {"Review/change scope", "Other..."}:
        reader = answer_reader or read_user_prompt
        try:
            text = reader("Plan revision> ")
        except TypeError:
            text = reader()
        if str(text or "").strip():
            return {"status": "revision_requested", "revision_text": str(text).strip(), "plan": plan}
    record = _plan_approval_record(plan, "REJECTED", "TERMINAL_ARROW_SELECTION")
    RUN["plan_approval"] = record
    RUN["plan_approval_rejected"] = RUN.get("plan_approval_rejected", 0) + 1
    record_run_event(
        "plan_rejected", plan_id=plan.get("plan_id"), plan_hash=plan.get("plan_hash"),
    )
    return {
        "status": "plan_rejected", "terminal_state": PLAN_REJECTED,
        "summary": "The proposed change plan was rejected; no subject files were mutated.",
        "plan": plan, "approval": record,
    }


def apply_plan_user_revision(contract, revision_text):
    """Add one explicit plan-scope decision without overwriting USER_STATED facts."""
    updated = copy.deepcopy(contract if isinstance(contract, dict) else {})
    text = str(revision_text or "").strip()
    if not text:
        return updated, None
    ledger = updated.get("source_requirement_ledger")
    ledger = append_confirmed_requirement(
        ledger, text, question_id="PLAN-REVISION-001", category="plan_scope",
        affected_requirement_ids=[
            item.get("requirement_id") for item in ledger_requirements(ledger)
        ][:8],
        repository_evidence_ids=[], phase="USER_PLAN_REVISION",
    )
    new_requirement = ledger_requirements(ledger, include_confirmed=True)[-1]
    decision = {
        "decision_id": "PLAN-DEC-001",
        "question_id": "PLAN-REVISION-001",
        "answer": compact_text(text, 700),
        "selected_option": "Review/change scope",
        "affected_requirement_ids": list(new_requirement.get("affected_requirement_ids", [])),
        "repository_evidence_ids": [],
        "phase": "USER_PLAN_REVISION",
        "provenance": USER_CONFIRMED,
        "requirement_id": new_requirement.get("requirement_id"),
    }
    updated["source_requirement_ledger"] = ledger
    updated["source_requirements"] = ledger_requirements(ledger)
    updated["user_stated_requirements"] = ledger_requirements(ledger)
    updated["user_confirmed_requirements"] = list(
        updated.get("user_confirmed_requirements", []) or []
    ) + [decision]
    updated["requirements"] = list(updated.get("requirements", []) or []) + [text]
    updated["source_contract"] = source_contract_from_ledger(
        updated.get("original_goal") or updated.get("goal") or text,
        ledger, confirmed=updated.get("user_confirmed_requirements", []),
        derived=updated.get("derived_assumptions", []),
        questions=updated.get("clarification_questions", []),
        answers=updated.get("clarification_answers", []),
        interaction_style=updated.get("interaction_style"),
    )
    RUN["source_requirement_ledger"] = ledger
    RUN["source_contract"] = updated["source_contract"]
    RUN["plan_user_revision"] = decision
    return updated, decision


def _stage3_workspace_fingerprint():
    if WORKSPACE is None:
        return None
    return stage2.inventory_repository(WORKSPACE).get("fingerprint")


def prepare_stage3_context(understanding, contract, interactive=True, terminal_available=None,
                           planner_structured_call=None, challenger_structured_call=None,
                           reviser_structured_call=None, approval_selector=None,
                           approval_answer_reader=None, verified_planning_context=None):
    """Create, challenge, gate, and approve the task-scoped existing-project plan."""
    understanding = understanding if isinstance(understanding, dict) else {}
    mode = understanding.get("project_mode")
    if mode in {NEW_PROJECT, EXISTING_PROJECT}:
        RUN["project_mode"] = mode
    if mode != EXISTING_PROJECT:
        RUN.setdefault("control_flow", []).append("IMPACT_PLANNING_SKIPPED_GREENFIELD")
        RUN["impact_planning_required"] = False
        return {"status": "ready", "contract": contract, "project_mode": mode}
    RUN["impact_planning_required"] = True
    fingerprint_before = _stage3_workspace_fingerprint()
    task_brain = understanding.get("task_brain") or RUN.get("task_brain") or {}
    RUN["task_brain"] = copy.deepcopy(task_brain)
    repository_evidence = list(
        (understanding.get("reconnaissance") or {}).get("evidence", [])
        or RUN.get("repository_evidence", []) or []
    )
    try:
        impact_map = create_impact_map(
            task_brain, contract, repository_evidence,
            structured_call=planner_structured_call,
            verified_planning_context=verified_planning_context,
        )
        challenge_validation = challenge_impact_map(
            impact_map, task_brain, contract, repository_evidence,
            structured_call=challenger_structured_call,
            verified_planning_context=verified_planning_context,
        )
        plan, gate = reconcile_minimal_change_plan(
            impact_map, challenge_validation, contract, repository_evidence,
            verified_planning_context=verified_planning_context,
        )
    except ImpactPlanningError as exc:
        return {
            "status": "plan_incomplete", "terminal_state": PLAN_INCOMPLETE,
            "summary": str(exc), "project_mode": mode,
            "orchestration_failure": RUN.get("orchestration_failure"),
            "planning_packet_status": getattr(exc, "status", None)
            or RUN.get("planning_packet_status"),
        }
    if not gate.get("valid"):
        fingerprint_after = _stage3_workspace_fingerprint()
        RUN["stage3_workspace_fingerprint_before"] = fingerprint_before
        RUN["stage3_workspace_fingerprint_after"] = fingerprint_after
        return {
            "status": "plan_incomplete", "terminal_state": PLAN_INCOMPLETE,
            "summary": "; ".join(gate.get("errors", [])),
            "project_mode": mode, "impact_map": impact_map,
            "plan": plan, "plan_gate": gate,
        }
    approval = request_plan_approval(
        plan, interactive=interactive, terminal_available=terminal_available,
        selector=approval_selector, answer_reader=approval_answer_reader,
        allow_revision=True,
    )
    if approval.get("status") == "revision_requested":
        contract, decision = apply_plan_user_revision(
            contract, approval.get("revision_text", ""),
        )
        try:
            impact_map = revise_impact_map(
                impact_map, challenge_validation.get("validated", []), task_brain,
                contract, repository_evidence, user_revision=decision,
                structured_call=reviser_structured_call,
                verified_planning_context=verified_planning_context,
            )
            # The one model Challenger is not invoked again. Deterministic
            # falsification still checks the revised map against the same facts.
            revised_challenges = stage3.deterministic_challenges(
                impact_map, _active_stage3_requirements(contract), repository_evidence,
                surface_registry=RUN.get("canonical_surface_registry"),
            )
            revised_validation = stage3.validate_challenges(
                revised_challenges, impact_map, _active_stage3_requirements(contract),
                repository_evidence,
                surface_registry=RUN.get("canonical_surface_registry"),
            )
            plan, gate = reconcile_minimal_change_plan(
                impact_map, revised_validation, contract, repository_evidence,
                verified_planning_context=verified_planning_context,
            )
        except ImpactPlanningError as exc:
            return {
                "status": "plan_incomplete", "terminal_state": PLAN_INCOMPLETE,
                "summary": str(exc), "project_mode": mode,
                "orchestration_failure": RUN.get("orchestration_failure"),
                "planning_packet_status": getattr(exc, "status", None)
                or RUN.get("planning_packet_status"),
            }
        if not gate.get("valid"):
            return {
                "status": "plan_incomplete", "terminal_state": PLAN_INCOMPLETE,
                "summary": "; ".join(gate.get("errors", [])),
                "project_mode": mode, "impact_map": impact_map,
                "plan": plan, "plan_gate": gate, "contract": contract,
            }
        approval = request_plan_approval(
            plan, interactive=interactive, terminal_available=terminal_available,
            selector=approval_selector, answer_reader=approval_answer_reader,
            allow_revision=False,
        )
    fingerprint_after = _stage3_workspace_fingerprint()
    RUN["stage3_workspace_fingerprint_before"] = fingerprint_before
    RUN["stage3_workspace_fingerprint_after"] = fingerprint_after
    RUN["stage3_read_only_before_approval"] = fingerprint_before == fingerprint_after
    if approval.get("status") != "approved":
        result = dict(approval)
        result.update({
            "project_mode": mode, "impact_map": impact_map,
            "plan": plan, "plan_gate": gate, "contract": contract,
            "read_only": fingerprint_before == fingerprint_after,
        })
        return result
    RUN["approved_change_plan"] = plan
    RUN["plan_approval"] = approval.get("approval")
    RUN["source_contract"] = copy.deepcopy(contract)
    execution_contracts = compile_approved_plan_execution_contracts(
        contract=contract, plan=plan, approval=RUN["plan_approval"],
    )
    if execution_contracts.get("status") != "ready":
        result = dict(execution_contracts)
        result.update({
            "project_mode": mode, "contract": contract,
            "impact_map": impact_map, "plan": plan,
            "plan_gate": gate, "approval": approval.get("approval"),
            "read_only": fingerprint_before == fingerprint_after,
        })
        return result
    return {
        "status": "ready", "project_mode": mode, "contract": contract,
        "impact_map": impact_map, "plan": plan, "plan_gate": gate,
        "approval": approval.get("approval"),
        "approved_plan_snapshot": execution_contracts.get("snapshot"),
        "execution_contracts": execution_contracts.get("contracts", []),
        "plan_execution_graph": execution_contracts.get("graph"),
        "read_only": fingerprint_before == fingerprint_after,
    }


def run_verified_state_aware_planning(
    fresh_task_brain=None,
    memory=None,
    *,
    reentry_context=None,
    verified_state_reentry=None,
    task_goal=None,
    contract=None,
    workspace=None,
    current_repository_evidence=None,
    expected_project_id=None,
    impact_planner_structured_call=None,
    impact_challenger_structured_call=None,
    impact_reviser_structured_call=None,
    reset=True,
    finish=True,
):
    """Run the V24 Stage 6B planning boundary from a fresh Stage 6A brain.

    This route intentionally starts after Stage 6A. It compiles and checks a
    deterministic planning projection, reuses the existing Stage 3 planning
    and challenge/reconciliation code, and stops at PLAN_APPROVAL_REQUIRED.
    It never performs Stage 2 discovery, execution-contract compilation,
    Worker execution, verification, promotion, or Project Brain mutation.
    """
    global WORKSPACE
    if workspace is not None:
        WORKSPACE = Path(workspace).expanduser().resolve()
    if reset:
        reset_run("recursive")
    elif RUN.get("mode") != "recursive":
        RUN["mode"] = "recursive"
    active_memory = memory if isinstance(memory, dict) else {}
    source = fresh_task_brain if fresh_task_brain is not None else verified_state_reentry
    context = stage6b.compile_verified_planning_context(
        source,
        reentry_context=reentry_context,
        expected_project_id=expected_project_id,
        current_repository_evidence=current_repository_evidence,
    )
    source_context = reentry_context
    if source_context is None and isinstance(source, dict):
        source_context = source.get("reentry_context")
    source_metrics = (
        source_context.get("metrics")
        if isinstance(source_context, dict) and isinstance(source_context.get("metrics"), dict)
        else {}
    )
    for key in (
        "verified_reentry_attempts", "project_brain_records_considered",
        "project_brain_records_current", "project_brain_records_stale",
        "project_brain_records_superseded", "project_brain_records_relevant",
        "project_brain_records_excluded", "reentry_conflicts",
        "authority_drift_checks", "authority_drift_confirmed",
        "authority_drift_consistent", "authority_drift_not_evaluable",
        "authority_drift_conflicts_emitted",
        "authority_drift_duplicate_conflicts_suppressed",
        "task_brain_bootstraps", "reentry_model_calls", "freshness_model_calls",
        "relevance_model_calls", "task_brain_bootstrap_model_calls",
        "automatic_reverification_attempts",
    ):
        if key in source_metrics:
            RUN[key] = int(source_metrics.get(key, 0) or 0)
    RUN["planning_mode"] = VERIFIED_STATE_REENTRY
    RUN["verified_planning_context"] = copy.deepcopy(context)
    RUN["verified_reentry_planning_calls"] = RUN.get("verified_reentry_planning_calls", 0) + 1
    RUN["planning_context_compiler_model_calls"] = int(context.get("model_calls", 0) or 0)
    if context.get("status") == "COMPILED" and context.get("valid") is True:
        RUN["verified_planning_contexts_created"] += 1
        RUN["planning_current_verified_items"] = len(context.get("current_verified_facts", []) or [])
        RUN["planning_stale_items_excluded"] = len(context.get("stale_evidence_warnings", []) or [])
        RUN["planning_confirmed_conflicts"] = len(context.get("confirmed_conflicts", []) or [])
        RUN["planning_not_evaluable_audits"] = len(context.get("not_evaluable_audit", []) or [])
    else:
        RUN["verified_planning_context_invalid"] += 1
        result = {
            "status": "planning_context_invalid",
            "terminal_state": PLANNING_CONTEXT_INVALID,
            "summary": "; ".join(context.get("errors", []) or [PLANNING_CONTEXT_INVALID]),
            "planning_context": context,
            "memory": active_memory,
        }
        if finish:
            finish_metrics(result["status"])
        return result, active_memory

    readiness = stage6b.assess_planning_context_readiness(
        context, current_repository_evidence=current_repository_evidence,
    )
    RUN["planning_readiness_model_calls"] = int(readiness.get("model_calls", 0) or 0)
    if readiness.get("ready") is True:
        RUN["verified_planning_context_ready"] += 1
    elif readiness.get("status") == PLANNING_CONTEXT_INSUFFICIENT_CURRENT_EVIDENCE:
        RUN["verified_planning_context_insufficient"] += 1
    elif readiness.get("status") == PLANNING_CONTEXT_STALE:
        RUN["verified_planning_context_stale"] += 1
    else:
        RUN["verified_planning_context_invalid"] += 1
    RUN["verified_planning_context_readiness"] = copy.deepcopy(readiness)
    if not readiness.get("ready"):
        terminal = readiness.get("status") or PLANNING_CONTEXT_INVALID
        result = {
            "status": "planning_context_not_ready",
            "terminal_state": terminal,
            "summary": readiness.get("reason") or terminal,
            "planning_context": context,
            "planning_context_readiness": readiness,
            "memory": active_memory,
        }
        if finish:
            finish_metrics(result["status"])
        return result, active_memory

    stage3_task_brain = stage6b.build_stage3_task_brain(context)
    # The compiled V24 context is the authoritative source for the planning
    # contract. A caller-supplied legacy contract is intentionally not allowed
    # to replace its requirement ledger or current-state bindings.
    planning_contract = stage6b.build_planning_contract(context)
    planning_contract.setdefault("project_id", context.get("project_id"))
    planning_contract["planning_mode"] = VERIFIED_STATE_REENTRY
    planning_contract["verified_planning_context_hash"] = context.get("planning_context_hash")
    begin_durable_run(planning_contract)
    RUN["project_mode"] = EXISTING_PROJECT
    RUN["impact_planning_required"] = True
    RUN["task_brain"] = copy.deepcopy(stage3_task_brain)
    RUN["repository_evidence"] = copy.deepcopy(context.get("current_repository_evidence", []) or [])
    RUN["verified_planning_context"] = copy.deepcopy(context)
    RUN["source_contract"] = copy.deepcopy(planning_contract)

    repository_evidence = list(context.get("current_repository_evidence", []) or [])
    requirements = _active_stage3_requirements(planning_contract)

    # The V24 entrypoint has a deterministic fallback for tests and local
    # architecture self-checks. A caller may supply the existing Stage 3
    # structured callbacks, but no V24 path implicitly starts a model role.
    planner_call = impact_planner_structured_call
    if planner_call is None:
        prohibited_paths = {
            str(item.get("path")).replace("\\", "/")
            for item in context.get("prohibitions", []) or []
            if isinstance(item, dict) and item.get("path") and re.search(
                r"\b(?:do not|don't|must not|never)\b",
                str(item.get("text") or ""), re.IGNORECASE,
            )
        }

        def deterministic_planner(*_args):
            frame = RUN.get("impact_decision_frame")
            if isinstance(frame, dict):
                result = stage3.deterministic_impact_decision_choices(frame)
                slots = {
                    str(item.get("slot_id")): item
                    for item in frame.get("decision_slots", []) or []
                    if isinstance(item, dict)
                }
                # The deterministic fixture respects an already-frozen DNT
                # by choosing the non-mutating bounded option when available.
                for decision in result.get("decisions", []) or []:
                    slot = slots.get(str(decision.get("slot_id")))
                    dnt = " ".join(str(item) for item in (slot or {}).get("dnt", []) or [])
                    if dnt and re.search(r"\b(?:do not|don't|must not|never)\b", dnt, re.IGNORECASE):
                        if "INSPECT_ONLY" in (slot or {}).get("allowed_decisions", []):
                            decision["decision"] = "INSPECT_ONLY"
                            decision["chosen_target"] = str(slot.get("surface_id"))
                            decision["reason_code"] = "INSPECT_CURRENT_SURFACE"
                            decision["bounded_rationale"] = (
                                "Inspect the verified prohibited surface without mutation."
                            )
                return result
            result = stage3.deterministic_impact_map(
                stage3_task_brain.get("task_goal", {}).get("text", task_goal or "coding task"),
                requirements, repository_evidence,
                registry=RUN.get("canonical_surface_registry"),
            )
            # The existing deterministic Stage 3 fallback maps behavior to
            # every owner surface. V24 applies the already-authoritative DNT
            # projection before planning so a forbidden owner file becomes a
            # verify/reuse surface rather than a mutation target.
            for impact in result.get("impacts", []) or []:
                if str(impact.get("path") or "").replace("\\", "/") in prohibited_paths:
                    impact["disposition"] = "VERIFY_ONLY"
                    impact["necessity_status"] = "CANDIDATE"
                    impact["candidate_change"] = "Verify the prohibited current surface without mutation."
                    impact["action"] = impact["candidate_change"]
            return result

        planner_call = deterministic_planner
    challenger_call = impact_challenger_structured_call
    if challenger_call is None:
        challenger_call = lambda *_args: {
            "challenges": stage3.deterministic_challenges(
                RUN.get("impact_map", {}), requirements, repository_evidence,
                surface_registry=RUN.get("canonical_surface_registry"),
            ),
        }

    understanding = {
        "status": "ready",
        "project_mode": EXISTING_PROJECT,
        "planning_mode": VERIFIED_STATE_REENTRY,
        "verified_planning_context": copy.deepcopy(context),
        "task_brain": copy.deepcopy(stage3_task_brain),
        "contract": copy.deepcopy(planning_contract),
        "project_brain": {
            "project_id": context.get("project_id"),
            "source_hash": context.get("source_project_brain_hash"),
            "read_only": True,
        },
        "reconnaissance": {
            "status": REPOSITORY_RECONNAISSANCE_COMPLETE,
            "evidence": copy.deepcopy(repository_evidence),
            "read_only": True,
            "operations": [],
            "source": "VERIFIED_STATE_REENTRY",
        },
        "repository_summary": {
            "source": "VERIFIED_STATE_REENTRY",
            "evidence_count": len(repository_evidence),
        },
        "specification": {"source": "VerifiedPlanningContext"},
    }
    try:
        planning = prepare_stage3_context(
            understanding,
            planning_contract,
            interactive=False,
            terminal_available=False,
            planner_structured_call=planner_call,
            challenger_structured_call=challenger_call,
            reviser_structured_call=impact_reviser_structured_call,
            verified_planning_context=context,
        )
    except (ImpactPlanningError, StructuredOutputError) as exc:
        planning = {
            "status": "plan_incomplete",
            "terminal_state": PLAN_INCOMPLETE,
            "summary": str(exc),
            "project_mode": EXISTING_PROJECT,
        }
    planning["planning_mode"] = VERIFIED_STATE_REENTRY
    planning["planning_context"] = copy.deepcopy(context)
    planning["planning_context_readiness"] = copy.deepcopy(readiness)
    planning["memory"] = active_memory
    if planning.get("status") == "plan_approval_required":
        planning["terminal_state"] = PLAN_APPROVAL_REQUIRED
        planning["approval_boundary"] = PLAN_APPROVAL_REQUIRED
    if finish:
        finish_metrics(planning.get("status", "failed"))
    return planning, active_memory


prepare_verified_state_aware_planning = run_verified_state_aware_planning
run_stage6b_planning = run_verified_state_aware_planning


def current_approved_change_plan():
    plan = RUN.get("approved_change_plan")
    approval = RUN.get("plan_approval")
    if stage3.approval_is_current(plan, approval):
        return plan
    return None


def _stage4_authoritative_goal(contract=None, plan=None):
    """Return the Stage 1/2 goal that the approved snapshot must preserve."""
    value = contract if isinstance(contract, dict) else {}
    goal = _authoritative_stage3_task_goal(value, RUN.get("task_brain"))
    if goal:
        return goal
    value = plan if isinstance(plan, dict) else RUN.get("approved_change_plan")
    return str((value or {}).get("task_goal") or (value or {}).get("goal") or "").strip()


def _stage4_failure_result(code, message, *, phase="execution_contract"):
    """Record a bounded Stage 4A failure and return its public state."""
    code = str(code or EXECUTION_CONTRACT_BLOCKED)
    if phase == "snapshot":
        RUN["approved_plan_snapshot_failures"] = RUN.get(
            "approved_plan_snapshot_failures", 0,
        ) + 1
    elif phase == "graph":
        RUN["execution_graph_failures"] = RUN.get("execution_graph_failures", 0) + 1
    else:
        RUN["execution_contract_failures"] = RUN.get(
            "execution_contract_failures", 0,
        ) + 1
    RUN["execution_contract_status"] = code
    RUN["orchestration_failure"] = code
    record_run_event(
        "execution_contract_blocked", terminal_state=code,
        phase=phase, error=compact_text(message, 1200),
    )
    return {
        "status": "blocked", "terminal_state": code,
        "orchestration_failure": code, "summary": compact_text(message, 1600),
    }


def _authority_bound_execution_attempt(task=None):
    """Detect an execution attempt that has entered approved authority mode.

    This deliberately relies on persisted plan/snapshot/contract state and
    existing authority status, never on the wording of a task.  A task-level
    contract marker is included for direct contract-bound callers; ordinary
    unbound ROOT tasks do not become authority-bound merely because they are
    running in recursive mode.
    """
    task = task if isinstance(task, dict) else {}
    run_artifacts = (
        isinstance(RUN.get("approved_change_plan"), dict),
        isinstance(RUN.get("approved_plan_snapshot"), dict),
        bool(RUN.get("execution_contracts")),
        isinstance(RUN.get("execution_contract_assignment"), dict)
        and bool(RUN.get("execution_contract_assignment")),
        RUN.get("execution_contract_status") in AUTHORITY_VALIDATION_FAILURES,
        RUN.get("orchestration_failure") in AUTHORITY_VALIDATION_FAILURES,
    )
    if any(run_artifacts):
        return True
    return bool(
        task.get("execution_contract_id")
        or task.get("execution_contract_hash")
        or task.get("approved_plan_id")
        or task.get("approved_plan_hash")
    ) and bool(
        RUN.get("project_mode") == EXISTING_PROJECT
        and RUN.get("impact_planning_required")
    )


def _authority_terminal_failure(task=None):
    """Return an existing terminal authority code, if one is active."""
    if not _authority_bound_execution_attempt(task):
        return None
    # ``execution_contract_status`` is the authoritative current status.  A
    # previous orchestration failure may remain in the run after a later valid
    # compile, so do not let that historical field mask a current ``ready``
    # status.
    status = RUN.get("execution_contract_status")
    if status in AUTHORITY_VALIDATION_FAILURES:
        # A root task without a snapshot, compiled contract, or task-level
        # contract binding may still use the deterministic injected leaf path
        # used by compatibility callers.  In that narrow pre-binding state,
        # EXECUTION_CONTRACT_BLOCKED is not enough to claim that a contract
        # authority was entered; the approved-plan/snapshot gate above still
        # fails closed for stale or missing approval.  Once a snapshot,
        # contract, or contract-bound task exists, the same status is terminal.
        if status != EXECUTION_CONTRACT_BLOCKED or (
            isinstance(RUN.get("approved_plan_snapshot"), dict)
            or bool(RUN.get("execution_contracts"))
            or bool((task or {}).get("execution_contract_id"))
            or bool((task or {}).get("execution_contract_hash"))
        ):
            return status
    if status == "ready":
        return None
    failure = RUN.get("orchestration_failure")
    if failure in AUTHORITY_VALIDATION_FAILURES:
        if failure != EXECUTION_CONTRACT_BLOCKED or (
            isinstance(RUN.get("approved_plan_snapshot"), dict)
            or bool(RUN.get("execution_contracts"))
            or bool((task or {}).get("execution_contract_id"))
            or bool((task or {}).get("execution_contract_hash"))
        ):
            return failure
    return None


def _authority_fail_closed_result(code, message="", base=None, task_id=None):
    """Turn a terminal authority result into an explicit no-fallback result."""
    code = str(code or EXECUTION_CONTRACT_BLOCKED)
    authority_status = (
        "STALE" if code == APPROVED_PLAN_STALE
        else "REQUIRED" if code == PLAN_APPROVAL_REQUIRED
        else "INVALID"
    )
    summary = compact_text(
        message or f"{code}: authority-bound execution terminated; generic fallback is disabled",
        1600,
    )
    record = {
        "execution_mode": "AUTHORITY_BOUND",
        "authority_status": authority_status,
        "terminal_reason": code,
        "fallback_allowed": False,
        "task_id": task_id,
    }
    RUN["authority_fail_closed_blocks"] = RUN.get("authority_fail_closed_blocks", 0) + 1
    RUN["authority_fail_closed_last"] = dict(record)
    record_run_event("authority_fail_closed", **record)
    result = dict(base) if isinstance(base, dict) else {}
    result.update({
        "status": "blocked",
        "terminal_state": code,
        "orchestration_failure": code,
        "summary": summary,
        **record,
    })
    return result


def compile_approved_plan_execution_contracts(contract=None, plan=None, approval=None,
                                              force=False, execution_invariant_set=None,
                                              verification_obligation_coverage=None):
    """Snapshot the approved Stage 3 plan and compile its deterministic DAG.

    This is the only entry point that creates Stage 4A authority.  It never
    calls a model and never runs a Worker.  Repeated calls revalidate the
    immutable snapshot and graph so a plan edit becomes a deterministic stale
    block instead of an implicit reapproval.
    """
    if (
        plan is None and approval is None
        and RUN.get("project_mode") != EXISTING_PROJECT
        and not RUN.get("impact_planning_required")
        and not RUN.get("stage6c_enabled")
    ):
        return {"status": "not_applicable", "contracts": [], "graph": None}
    if (
        RUN.get("stage6c_enabled")
        and isinstance(RUN.get("approval_request"), dict)
        and isinstance(RUN.get("approval_receipt"), dict)
        and isinstance(RUN.get("pre_execution_approval_revalidation"), dict)
        and isinstance(RUN.get("execution_authorization"), dict)
    ):
        bound_plan = plan if isinstance(plan, dict) else RUN.get("approved_change_plan")
        try:
            bound = compile_approval_bound_execution_contracts(
                bound_plan,
                RUN.get("approval_receipt"),
                RUN.get("pre_execution_approval_revalidation"),
                RUN.get("execution_authorization"),
                request=RUN.get("approval_request"),
                requirements=(bound_plan or {}).get("requirements", []) if isinstance(bound_plan, dict) else None,
                repository_evidence=RUN.get("repository_evidence", []) or [],
                canonical_surface_registry=RUN.get("canonical_surface_registry"),
                authoritative_task_goal=_stage4_authoritative_goal(contract, bound_plan),
                execution_invariant_set=(
                    execution_invariant_set
                    if execution_invariant_set is not None
                    else RUN.get("execution_invariant_set")
                ),
                execution_invariant_source_root=RUN.get("execution_workspace"),
                verification_obligation_coverage=(
                    verification_obligation_coverage
                    if verification_obligation_coverage is not None
                    else RUN.get("verification_obligation_coverage")
                ),
            )
        except stage6c.ApprovalAuthorityError as exc:
            return _stage4_failure_result(
                getattr(exc, "code", EXECUTION_AUTHORIZATION_BLOCKED),
                str(exc), phase="approval_binding",
            )
        RUN["approved_plan_snapshot"] = bound.get("snapshot")
        RUN["approved_plan_snapshot_hash"] = (bound.get("snapshot") or {}).get("snapshot_hash")
        RUN["execution_contracts"] = bound.get("contracts", [])
        RUN["plan_execution_graph"] = bound.get("graph")
        RUN["execution_contract_status"] = "ready"
        return bound
    contract = contract if isinstance(contract, dict) else RUN.get("source_contract")
    plan = plan if isinstance(plan, dict) else RUN.get("approved_change_plan")
    approval = approval if isinstance(approval, dict) else RUN.get("plan_approval")
    authoritative_goal = _stage4_authoritative_goal(contract, plan)
    approval_validation = (
        stage4.validate_approved_plan(
            plan, approval, authoritative_goal, current_plan=plan,
        )
        if isinstance(plan, dict) else {
            "valid": False, "code": PLAN_APPROVAL_REQUIRED,
            "errors": ["current approved plan is missing"],
        }
    )
    if not approval_validation.get("valid"):
        RUN["plan_approval_required"] = RUN.get("plan_approval_required", 0) + 1
        if approval_validation.get("code") == APPROVED_PLAN_STALE:
            RUN["execution_contract_stale_blocks"] = RUN.get(
                "execution_contract_stale_blocks", 0,
            ) + 1
        return _stage4_failure_result(
            approval_validation.get("code") or PLAN_APPROVAL_REQUIRED,
            "; ".join(approval_validation.get("errors", []))
            or "Stage 4A requires APPROVED approval for the current canonical plan hash.",
            phase="snapshot",
        )
    existing = RUN.get("approved_plan_snapshot")
    if not force and isinstance(existing, dict):
        if not stage4.snapshot_is_current(existing, plan, approval, authoritative_goal):
            RUN["execution_contract_stale_blocks"] = RUN.get(
                "execution_contract_stale_blocks", 0,
            ) + 1
            return _stage4_failure_result(
                APPROVED_PLAN_STALE,
                "ApprovedPlanSnapshot is stale relative to the current canonical plan or approval.",
                phase="snapshot",
            )
        stored_graph = RUN.get("plan_execution_graph")
        stored_contracts = RUN.get("execution_contracts", [])
        if isinstance(stored_graph, dict) and isinstance(stored_contracts, list):
            graph_check = stage4.validate_execution_graph(
                existing, stored_graph, stored_contracts,
            )
            if graph_check.get("valid"):
                return {
                    "status": "ready", "snapshot": existing,
                    "contracts": stored_contracts, "assignment": RUN.get(
                        "execution_contract_assignment", {},
                    ), "graph": stored_graph,
                    "validation": graph_check,
                }
            return _stage4_failure_result(
                EXECUTION_GRAPH_INVALID,
                "; ".join(graph_check.get("errors", [])) or "stored execution graph is invalid",
                phase="graph",
            )
    try:
        snapshot = stage4.create_approved_plan_snapshot(
            plan, approval, authoritative_task_goal=authoritative_goal,
            requirements=_active_stage3_requirements(contract),
            repository_evidence=RUN.get("repository_evidence", []) or [],
            canonical_surface_registry=RUN.get("canonical_surface_registry"),
        )
    except stage4.ExecutionContractError as exc:
        return _stage4_failure_result(exc.code, str(exc), phase="snapshot")
    RUN["approved_plan_snapshots_validated"] = RUN.get(
        "approved_plan_snapshots_validated", 0,
    ) + 1
    RUN["approved_plan_snapshot"] = snapshot
    RUN["approved_plan_snapshot_hash"] = snapshot.get("snapshot_hash")
    RUN.setdefault("control_flow", []).append("APPROVED_PLAN_SNAPSHOT")
    record_run_event(
        "approved_plan_snapshot_validated", plan_id=snapshot.get("plan_id"),
        plan_hash=snapshot.get("plan_hash"),
        snapshot_hash=snapshot.get("snapshot_hash"),
    )
    try:
        compiled = stage4.compile_execution_contracts(snapshot)
        contracts = compiled.get("contracts", [])
        graph = stage4.build_execution_graph(snapshot, contracts)
        graph_validation = stage4.validate_execution_graph(snapshot, graph, contracts)
        if not graph_validation.get("valid"):
            raise stage4.ExecutionGraphError(
                EXECUTION_GRAPH_INVALID,
                "; ".join(graph_validation.get("errors", [])),
            )
    except stage4.ExecutionGraphError as exc:
        return _stage4_failure_result(exc.code, str(exc), phase="graph")
    except stage4.ExecutionContractError as exc:
        return _stage4_failure_result(exc.code, str(exc), phase="execution_contract")
    RUN["execution_contracts"] = contracts
    RUN["execution_contract_by_id"] = {
        item.get("execution_contract_id"): item for item in contracts
    }
    RUN["execution_contract_assignment"] = compiled.get("assignment", {})
    RUN["execution_contract_validation"] = compiled.get("validation", {})
    RUN["plan_execution_graph"] = graph
    RUN["execution_graph_validation"] = graph_validation
    for key in (
        "execution_contracts_created", "execution_contract_mutation",
        "execution_contract_test", "execution_contract_verify_only",
    ):
        RUN[key] = RUN.get(key, 0) + int(compiled.get("metrics", {}).get(key, 0) or 0)
    RUN["execution_graphs_created"] = RUN.get("execution_graphs_created", 0) + 1
    RUN["execution_contract_status"] = "ready"
    RUN.setdefault("control_flow", []).append("EXECUTION_CONTRACT_COMPILATION")
    RUN.setdefault("control_flow", []).append("PLAN_EXECUTION_GRAPH")
    record_run_event(
        "execution_contracts_compiled", plan_id=snapshot.get("plan_id"),
        plan_hash=snapshot.get("plan_hash"),
        snapshot_hash=snapshot.get("snapshot_hash"),
        contract_ids=[item.get("execution_contract_id") for item in contracts],
        graph_hash=graph.get("graph_hash"),
    )
    return {
        "status": "ready", "snapshot": snapshot, "contracts": contracts,
        "assignment": compiled.get("assignment", {}), "graph": graph,
        "validation": graph_validation,
    }


