def _mock_contract():
    return {"status": "ready", "goal": "Build hard mock", "requirements": ["a", "b", "c"],
            "constraints": ["local"], "success_criteria": ["verified"], "original_goal": "Build hard mock"}


def run_dependency_scheduler_self_test():
    """Exercise V19.5 failure isolation with deterministic Worker stubs."""
    saved = {
        name: globals()[name]
        for name in (
            "WORKSPACE", "RUN", "TASKS", "ROLE_STATUS", "DASHBOARD", "RUN_STARTED", "RUN_ID",
            "ACTIVE_TRANSACTION", "LAST_COMMITTED_TRANSACTION", "ACTIVE_CONTRACT", "ACTIVE_TOOL_CONTRACT",
            "MEMORY_STORE", "FORCE_CPU_FOR_RUN", "VISION_ENABLED_FOR_RUN", "VISION_ERROR",
            "PREFLIGHT_CONFLICT_STATE",
        )
    }

    def scenario(specs, failures):
        reset_run("recursive")
        contract = {
            "status": "ready", "goal": "deterministic scheduler self-test",
            "requirements": ["all child states are accounted for"],
            "success_criteria": ["parent preserves strict failure"],
        }
        parent = make_task("P", contract["goal"], 0, "ROOT", ["children accounted"], [])
        children = []
        for child_id, dependency_ids in specs:
            child = make_task(
                child_id, f"self-test {child_id}", 1, "P", [f"{child_id} complete"], [],
            )
            child["dependencies"] = list(dependency_ids)
            children.append(child)
            TASKS[child_id] = child
            parent["children"].append(child_id)
        TASKS["P"] = parent
        RUN["tasks_created"] = len(children) + 1
        fit_calls = []
        leaf_calls = []

        def fit(child, *_args):
            fit_calls.append(child["id"])
            return {"decision": "execute"}

        def leaf(child, _contract, memory, _repo, _parent, _dependencies):
            leaf_calls.append(child["id"])
            if child["id"] in failures:
                return {
                    "status": "failed", "failure_type": "VERIFICATION_TARGET_UNRESOLVED",
                    "summary": "deterministic child failure", "memory": memory,
                }
            return {"status": "done", "summary": "deterministic child success", "memory": memory}

        def aggregate(_task, _contract, _children, memory, _repo, root=False):
            return {"status": "done", "summary": "all children passed", "memory": memory}

        result = _execute_children(
            parent, children, 0, contract, {}, {"files": []}, "", [],
            fit_decider=fit, leaf_executor=leaf, aggregator=aggregate,
        )
        return {
            "result": result, "parent": parent, "children": children,
            "fit_calls": fit_calls, "leaf_calls": leaf_calls,
            "metrics": copy.deepcopy(RUN),
        }

    try:
        with tempfile.TemporaryDirectory(prefix="mini_hivo_scheduler_selftest_", ignore_cleanup_errors=True) as tmp:
            WORKSPACE = Path(tmp)
            MEMORY_STORE = None
            independent = scenario(
                [("A", []), ("B", []), ("C", [])], {"A"},
            )
            dependent = scenario(
                [("A", []), ("B", []), ("C", ["A"])], {"A"},
            )
            transitive = scenario(
                [("A", []), ("B", ["A"]), ("C", ["B"]), ("D", [])], {"A"},
            )
            independent_statuses = {
                child["id"]: child["status"] for child in independent["children"]
            }
            dependent_statuses = {
                child["id"]: child["status"] for child in dependent["children"]
            }
            transitive_statuses = {
                child["id"]: child["status"] for child in transitive["children"]
            }
            checks = {
                "independent siblings continue": (
                    independent["leaf_calls"] == ["A", "B", "C"]
                    and independent_statuses == {"A": "failed", "B": "done", "C": "done"}
                    and independent["result"].get("status") == "failed"
                ),
                "explicit dependency blocks": (
                    dependent["leaf_calls"] == ["A", "B"]
                    and dependent_statuses == {"A": "failed", "B": "done", "C": "blocked"}
                    and dependent["children"][2]["child_scheduler"].get("blocked_by") == ["A"]
                ),
                "transitive dependency blocks": (
                    transitive["leaf_calls"] == ["A", "D"]
                    and transitive_statuses == {"A": "failed", "B": "blocked", "C": "blocked", "D": "done"}
                ),
                "strict parent failure": (
                    independent["result"].get("status") == "failed"
                    and dependent["result"].get("status") == "failed"
                ),
                "no model calls": all(
                    item["metrics"].get("model_calls", 0) == 0
                    for item in (independent, dependent, transitive)
                ),
            }
            return {"passed": all(checks.values()), "checks": checks}
    finally:
        for name, value in saved.items():
            globals()[name] = value


def run_verification_applicability_self_test():
    """Exercise Stage 5A routing with tiny local fixtures and no model/browser."""
    saved = {
        name: globals()[name]
        for name in (
            "WORKSPACE", "RUN", "TASKS", "ROLE_STATUS", "DASHBOARD", "RUN_STARTED", "RUN_ID",
            "ACTIVE_TRANSACTION", "LAST_COMMITTED_TRANSACTION", "ACTIVE_CONTRACT", "ACTIVE_TOOL_CONTRACT",
            "MEMORY_STORE", "FORCE_CPU_FOR_RUN", "VISION_ENABLED_FOR_RUN", "VISION_ERROR",
            "PREFLIGHT_CONFLICT_STATE",
        )
    }

    def write(root, relative, content="const ready = true;\n"):
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")

    try:
        with tempfile.TemporaryDirectory(prefix="mini_hivo_verification_selftest_", ignore_cleanup_errors=True) as tmp:
            globals()["WORKSPACE"] = Path(tmp)
            reset_run("recursive")
            write(WORKSPACE, "src/input.js")
            write(WORKSPACE, "src/module.js")
            write(WORKSPACE, "tests/module.test.js", "test('module', () => { if (!true) throw Error(); });\n")
            repository = inspect_repository()
            module_task = {
                "id": "SELF-NON-BROWSER",
                "goal": "Implement the non-browser module",
                "done_when": ["the module behavior is verified"],
                "scope_hint": ["src/module.js"],
                "test_contract": ["tests/module.test.js passes"],
                "allowed_inspection_paths": ["src/module.js", "tests/module.test.js"],
            }
            module_artifact = analyze_verification_applicability(
                module_task, module_task, repository,
            )
            module_browser = _verification_route(module_artifact, BROWSER_VERIFICATION)
            module_builder = {
                "status": "done",
                "tool_evidence": [{
                    "tool": "run_command", "target": "node --check src/module.js",
                    "result": "[exit_code=0]",
                }, {
                    "tool": "run_command", "target": "node tests/module.test.js",
                    "result": "[exit_code=0] module test ok",
                }],
            }
            module_focused = _verification_route(module_artifact, FOCUSED_TEST)
            module_skip = _verification_skip_result(module_task, module_artifact, module_browser)
            module_skip["verification_applicability"] = _update_verification_applicability_result(
                module_artifact, None, BROWSER_VERIFICATION, module_skip,
            )
            module_gate = evidence_gate(module_builder, browser_result=module_skip)

            missing_task = {
                "id": "SELF-BROWSER-MISSING",
                "goal": "Verify browser-rendered behavior",
                "done_when": ["browser-visible behavior works"],
                "scope_hint": ["src/input.js"],
            }
            missing_artifact = analyze_verification_applicability(
                missing_task, missing_task, repository,
            )
            missing_browser = _verification_route(missing_artifact, BROWSER_VERIFICATION)
            html_task = {
                "id": "SELF-BROWSER-PRESENT",
                "goal": "Verify browser-rendered behavior",
                "done_when": ["browser-visible behavior works"],
                "scope_hint": [],
            }
            write(WORKSPACE, "index.html", "<!doctype html><title>Self Test</title>")
            html_repository = inspect_repository()
            html_artifact = analyze_verification_applicability(
                html_task, html_task, html_repository,
            )
            html_browser = _verification_route(html_artifact, BROWSER_VERIFICATION)
            no_evidence = aggregate_verification_evidence(
                module_artifact, [], module_skip,
            )
            checks = {
                "non-browser optional skip": (
                    module_browser.get("required") is False
                    and module_browser.get("applicable") is False
                    and module_browser.get("result") == SKIPPED_NOT_APPLICABLE
                    and module_gate.get("passed") is True
                    and RUN.get("browser_checks", 0) == 0
                ),
                "focused test route": (
                    module_focused is not None
                    and module_focused.get("required") is True
                    and module_focused.get("applicable") is True
                    and module_focused.get("target") == "tests/module.test.js"
                ),
                "browser required but missing": (
                    missing_browser.get("required") is True
                    and missing_browser.get("applicable") is True
                    and missing_browser.get("target") is None
                    and missing_browser.get("resolution_status") == VERIFICATION_TARGET_UNRESOLVED
                ),
                "browser required and present": (
                    html_browser.get("required") is True
                    and html_browser.get("applicable") is True
                    and html_browser.get("target") == "index.html"
                ),
                "no evidence fails closed": (
                    no_evidence.get("passed") is False
                    and VERIFICATION_EVIDENCE_UNAVAILABLE in no_evidence.get("failure_codes", [])
                ),
                "zero model calls": all(
                    artifact.get("model_calls") == 0
                    for artifact in (module_artifact, missing_artifact, html_artifact)
                ),
            }
            return {"passed": all(checks.values()), "checks": checks}
    finally:
        for name, value in saved.items():
            globals()[name] = value


def run_verified_child_integration_self_test():
    """Exercise the V21 readiness/receipt/integration boundary without models."""
    def child(root, child_id, source, status="done", failure_type=None):
        focused = f"tests/{child_id.lower()}.test.js"
        contract_hash = f"CONTRACT-{child_id}"
        task = {
            "id": child_id, "parent": "PARENT", "status": status,
            "goal": f"Implement {child_id}", "done_when": [f"{child_id} is verified"],
            "plan_node_ids": [f"NODE-{child_id}"],
            "owned_plan_node_ids": [f"NODE-{child_id}"],
            "execution_contract_id": f"EXEC-{child_id}",
            "execution_contract": {
                "execution_contract_id": f"EXEC-{child_id}",
                "contract_hash": contract_hash, "plan_hash": "PARENT-PLAN",
                "plan_node_ids": [f"NODE-{child_id}"],
                "owned_plan_node_ids": [f"NODE-{child_id}"],
                "allowed_mutation_paths": [source],
                "done_when": [f"{child_id} is verified"],
            },
        }
        routes = [
            {"kind": "FOCUSED_TEST", "required": True, "applicable": True,
             "target": focused, "result": "PENDING"},
            {"kind": "SYNTAX_STATIC_GATE", "required": True, "applicable": True,
             "target": source, "result": "PENDING"},
            {"kind": "BROWSER", "required": False, "applicable": False,
             "target": None, "result": SKIPPED_NOT_APPLICABLE},
        ]
        passed = status == "done"
        aggregation = {
            "passed": passed, "evidence_available": passed,
            "failure_codes": [] if passed else ["REQUIRED_VERIFICATION_FAILED"],
            "actual_passes": [dict(route, result=VERIFICATION_PASS) for route in routes[:2]] if passed else [],
            "actual_failures": [] if passed else [dict(routes[0], result=VERIFICATION_FAIL)],
            "skipped_not_applicable": [routes[2]],
            "verification_routes": routes,
        }
        result = {
            "status": status, "summary": f"{child_id} self-test result",
            "failure_type": failure_type,
            "gate": {"verification_aggregation": aggregation},
            "builder": {"status": status, "tool_evidence": [{
                "tool": "run_command", "target": f"node {focused}",
                "result": "[exit_code=0] focused test passed",
            }] if passed else []},
        }
        receipt = _create_verified_child_receipt_v21(
            task, result, parent_id="PARENT",
            parent_contract={
                "contract_hash": "PARENT-CONTRACT", "plan_hash": "PARENT-PLAN",
            }, workspace=root,
        )
        return task, result, receipt

    with tempfile.TemporaryDirectory(
        prefix="mini_hivo_verified_child_selftest_", ignore_cleanup_errors=True,
    ) as tmp:
        root = Path(tmp)
        for relative, content in (
            ("src/a.js", "export const a = 1;\n"),
            ("src/b.js", "export const b = 1;\n"),
            ("tests/a.test.js", "const a = require('../src/a.js'); test('a', () => a);\n"),
            ("tests/b.test.js", "const b = require('../src/b.js'); test('b', () => b);\n"),
            ("tests/integration.test.js", "test('integration', () => {});\n"),
        ):
            path = root / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        parent = {
            "id": "PARENT", "goal": "integrate approved responsibilities",
            "integration_routes": [
                {"kind": "INTEGRATION_TEST", "required": True, "applicable": True,
                 "target": "tests/integration.test.js", "result": "PENDING"},
                {"kind": "BROWSER", "required": False, "applicable": False,
                 "target": None, "result": SKIPPED_NOT_APPLICABLE},
            ],
        }
        parent_contract = {
            "contract_hash": "PARENT-CONTRACT", "plan_hash": "PARENT-PLAN",
            "execution_contract_id": "PARENT",
        }
        plan = [
            {"child_id": "A", "required": True, "execution_contract_id": "EXEC-A",
             "contract_hash": "CONTRACT-A", "plan_node_ids": ["NODE-A"],
             "owned_plan_node_ids": ["NODE-A"]},
            {"child_id": "B", "required": True, "execution_contract_id": "EXEC-B",
             "contract_hash": "CONTRACT-B", "plan_node_ids": ["NODE-B"],
             "owned_plan_node_ids": ["NODE-B"]},
        ]
        a = child(root, "A", "src/a.js")
        b = child(root, "B", "src/b.js")
        fresh_pairs = [(a[0], a[1]), (b[0], b[1])]
        fresh_receipts = {"A": a[2], "B": b[2]}
        partial_c = child(root, "C", "src/a.js", status="failed", failure_type="MISSION_COMPILER_REJECTED")
        partial_plan = plan + [{
            "child_id": "C", "required": True, "execution_contract_id": "EXEC-C",
            "contract_hash": "CONTRACT-C", "plan_node_ids": ["NODE-C"],
            "owned_plan_node_ids": ["NODE-C"],
        }]
        partial_gate = _assess_integration_readiness_v21(
            parent, fresh_pairs + [(partial_c[0], partial_c[1])], {"A": a[2]},
            parent_contract=parent_contract, validated_child_plan=partial_plan,
            workspace=root,
        )
        partial_integration = _aggregate_parent_integration_v21(
            parent, parent_contract, partial_gate, [], workspace=root,
        )
        fresh_gate = _assess_integration_readiness_v21(
            parent, fresh_pairs, fresh_receipts, parent_contract=parent_contract,
            validated_child_plan=plan, workspace=root,
        )
        (root / "src/a.js").write_text("export const a = 2;\n", encoding="utf-8")
        stale_gate = _assess_integration_readiness_v21(
            parent, fresh_pairs, fresh_receipts, parent_contract=parent_contract,
            validated_child_plan=plan, workspace=root,
        )
        (root / "src/a.js").write_text("export const a = 1;\n", encoding="utf-8")
        pass_result = _aggregate_parent_integration_v21(
            parent, parent_contract, fresh_gate, [{
                "tool": "run_command", "target": "node tests/integration.test.js",
                "result": "[exit_code=0] integration passed",
            }], workspace=root,
        )
        fail_result = _aggregate_parent_integration_v21(
            parent, parent_contract, fresh_gate, [{
                "tool": "run_command", "target": "node tests/integration.test.js",
                "result": "[exit_code=1] integration failed",
            }], workspace=root,
        )
        checks = {
            "partial tree not ready": (
                partial_gate.get("reason") == NOT_READY_CHILD_FAILURE
                and partial_integration.get("status") == INTEGRATION_NOT_READY
                and partial_integration.get("integration_executor_calls") == 0
            ),
            "all fresh ready": (
                fresh_gate.get("readiness") == "READY"
                and fresh_gate.get("model_calls") == 0
            ),
            "stale evidence not ready": (
                stale_gate.get("reason") == NOT_READY_STALE_EVIDENCE
                and stale_gate.get("freshness", {}).get("stale_child_ids") == ["A"]
            ),
            "integration pass creates parent receipt": (
                pass_result.get("status") == PARENT_VERIFIED
                and (pass_result.get("parent_verification_receipt") or {}).get("verified") is True
            ),
            "integration fail stays unverified": (
                fail_result.get("status") == INTEGRATION_FAILED
                and fail_result.get("parent_verified") is False
                and "parent_verification_receipt" not in fail_result
            ),
            "skip is not pass": SKIPPED_NOT_APPLICABLE != VERIFICATION_PASS,
            "zero model calls": (
                all(item.get("model_calls") == 0 for item in (partial_gate, fresh_gate, stale_gate))
                and (pass_result.get("parent_verification_receipt") or {}).get("provenance", {}).get("model_calls") == 0
            ),
        }
        return {"passed": all(checks.values()), "checks": checks}


def run_self_test(install_browser=False):
    global WORKSPACE
    print("[SELF TEST]")
    with tempfile.TemporaryDirectory(prefix="mini_hivo_selftest_", ignore_cleanup_errors=True) as tmp:
        WORKSPACE = Path(tmp)
        memory = load_memory()
        contract = _mock_contract()
        repo = inspect_repository()
        reset_run("recursive")
        expanded_specification = normalize_project_specification(
            contract["original_goal"], contract,
            {
                "root_goal": contract["goal"],
                "user_visible_behavior": ["the mock project exposes verified outcomes"],
                "major_functional_areas": ["mock loop behavior", "mock persistence behavior"],
                "major_system_components": ["mock loop owner"],
                "state_ownership": ["mock state has one authoritative owner"],
                "interaction_model": ["mock interaction triggers the loop"],
                "ui_ux_expectations": [], "persistence_requirements": [],
                "important_edge_cases": ["mock loop does not duplicate itself"],
                "architecture_invariants": ["preserve one authoritative mock loop"],
                "interface_contracts": ["mock loop exposes a verified state interface"],
                "quality_constraints": [],
                "project_specific_coding_constraints": ["keep mock update and render ownership separate"],
                "acceptance_criteria": ["mock loop is verified"],
                "explicit_assumptions": [],
                "unresolved_critical_ambiguities": [],
                "non_goals": ["unrelated enemy AI"],
            },
        )
        project_brain = prepare_project_brain(
            contract["original_goal"], contract, repo, specification=expanded_specification,
        )
        mission_task = make_task(
            "self-test-mission", "Implement the mock loop", 1, "ROOT",
            ["mock loop is verified"], ["game.js"],
        )
        mission_projection = build_brain_projection(
            project_brain, mission_task, repo_snapshot=repo,
        )
        compiler_prompts = []

        def fake_mission_structured(prompt_text, _validator, _label, _schema):
            compiler_prompts.append(prompt_text)
            return {
                "goal_anchor": "ignored model anchor",
                "task": "ignored model task",
                "expected_outcome": "the mock loop is verified",
                "targets": ["game.js"],
                "existing_facts": ["reuse the verified state owner"],
                "implementation_plan": ["extend the existing loop owner"],
                "interfaces_to_reuse": ["mock loop state interface"],
                "invariants": ["preserve one authoritative mock loop"],
                "project_specific_quality_rules": ["keep update and render ownership separate"],
                "do_not": ["create a second loop"],
                "verification_plan": ["run deterministic mock loop verification"],
                "done_when": ["model output should not replace the task contract"],
            }

        compiled_mission = compile_worker_mission(
            mission_task, mission_projection, repo_snapshot=repo,
            structured_call=fake_mission_structured,
        )
        first_packet = build_node_context(
            make_task("fresh-a", "Implement the first mock behavior", 1, "ROOT", ["first verified"], []),
            contract, None, repo, brain_projection=mission_projection,
            worker_mission=compiled_mission,
        )
        second_packet = build_node_context(
            make_task("fresh-b", "Implement the second mock behavior", 1, "ROOT", ["second verified"], []),
            contract, None, repo, brain_projection=mission_projection,
        )
        captured_worker_messages = []
        original_ask_ollama = globals()["ask_ollama"]

        def fake_worker_call(messages, **_kwargs):
            captured_worker_messages.append(copy.deepcopy(messages))
            return {"role": "assistant", "content": "mocked worker response"}

        globals()["ask_ollama"] = fake_worker_call
        try:
            execute_agent_task("first node", {}, task_id="self-test-a", extra_context="FIRST_ONLY", max_steps=1)
            execute_agent_task("second node", {}, task_id="self-test-b", extra_context="SECOND_ONLY", max_steps=1)
        finally:
            globals()["ask_ollama"] = original_ask_ollama
        root = root_task_from_contract(contract); TASKS["ROOT"] = root; RUN["tasks_created"] = 1

        def fit(task, depth, contract, repo, parent, deps, force):
            if force:
                return {"decision": "split"}
            if depth < 3 and task["id"] in {"ROOT", "1", "2", "2.2"}:
                return {"decision": "split"}
            return {"decision": "execute"}

        def leaf(task, contract, mem, repo, parent, deps):
            RUN["leaf_tasks"] += 1
            return {"status": "done", "summary": f"verified {task['id']}", "memory": mem, "changed_files": []}

        def aggregate(task, contract, children, mem, repo, root=False):
            return {"status": "done", "summary": "verified aggregate", "memory": mem, "changed_files": []}

        # deterministic decomposition fallback avoids any live model call
        original_decompose = globals()["decompose_task"]
        def fake_decompose(task, contract, repo, parent_summary="", dependency_summaries=None, force_smaller=False):
            remaining = MAX_TOTAL_TASKS - RUN["tasks_created"]
            if remaining < 2:
                return []
            specs = [{"goal": f"{task['goal']} part A", "done_when": ["A"], "scope_hint": []},
                     {"goal": f"{task['goal']} part B", "done_when": ["B"], "scope_hint": []}]
            children=[]
            for i,spec in enumerate(specs,1):
                cid=str(i) if task['id']=='ROOT' else f"{task['id']}.{i}"
                child=make_task(cid,spec['goal'],task['depth']+1,task['id'],spec['done_when'],[])
                TASKS[cid]=child; task['children'].append(cid); RUN['tasks_created']+=1; children.append(child)
            return children
        globals()["decompose_task"] = fake_decompose
        try:
            result = solve_task(root, 0, contract, memory, repo, fit_decider=fit, leaf_executor=leaf, aggregator=aggregate)
        finally:
            globals()["decompose_task"] = original_decompose
        # Host qualification is tested with injected deterministic probes so
